    [8930] = {
        achievementId = 8930,
        name = "Ya, We've Got Time...",
        source = "Ya, We've Got Time...",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Kill four Primal Elementalists inside one ten-second window.",
        acquisition = "Difficulty: Medium - Kill four Primal Elementalists inside one ten-second window.\n\n1. Enter Blackrock Foundry on Normal or higher. Remove damaging procs, pets and automatic cleave when preserving enemies or waiting for a phase. \n\n2. Complete Blast Furnace's first phase: use engineers' bombs to destroy both Heat Regulators. In phase two keep all four Primal Elementalists alive until ready for a synchronized kill.\n\n3. At high level, damage can penetrate their reduction shields. Kill healing Firecallers away from the four targets and dispel Reactive Earth Shield if it heals them. Position for a quick circuit or distribute players among the four.\n\n4. Kill ALL FOUR within ten seconds measured from the first death, then defeat the Heart of the Mountain. If your damage cannot penetrate shields, gather a Slag Elemental beside each, kill those simultaneously to expose all four, then execute the synchronized kill.",
        stepCount = 4,
        waypoints = { { mapID = 543, x = 0.516, y = 0.287, step = 1, label = "Blackrock Foundry - Ya, We've Got Time..." } },
        sources = {
            "https://www.wowhead.com/achievement=8930",
            "https://www.wowhead.com/achievement=8930#comments:id=2100588",
            "https://www.wowhead.com/achievement=8930#comments:id=2499929",
            "https://www.wowhead.com/achievement=8930#comments:id=2580528",
            "https://www.wowhead.com/achievement=8930#comments:id=2605870",
        },
        sourceURL = "https://www.wowhead.com/achievement=8930#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=8930",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [8932] = {
        achievementId = 8932,
        name = "Mythic: Flamebender Ka'graz",
        source = "Mythic: Flamebender Ka'graz",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "An ordinary legacy Mythic kill; no guild or seasonal deadline.",
        acquisition = "Difficulty: Easy - An ordinary legacy Mythic kill; no guild or seasonal deadline.\n\n1. Set RAID difficulty to Mythic before entering Blackrock Foundry at the map pin. Dungeon difficulty does not select the raid's mode.\n\n2. Clear the three wings. Reach the Iron Maidens by the drop near Thogar's train station. For Blast Furnace, use dropped bombs on both Heat Regulators, defeat the exposed Primal Elementalists and kill the Heart of the Mountain. Complete the wings to open Blackhand's route.\n\n3. Defeat Flamebender Ka'graz on Mythic and check the achievement. Normal, Heroic and Raid Finder kills do not replace Mythic. The retired Ahead of the Curve and Cutting Edge feats are separate records.",
        stepCount = 3,
        waypoints = { { mapID = 543, x = 0.516, y = 0.287, step = 1, label = "Blackrock Foundry - Mythic entrance" } },
        sources = { "https://www.wowhead.com/achievement=8932" },
        sourceURL = "https://www.wowhead.com/achievement=8932#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=8932",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [8933] = {
        achievementId = 8933,
        name = "Staying Regular",
        source = "Staying Regular",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Interact with your Garrison's usable outhouse.",
        acquisition = "Difficulty: Easy - Interact with your Garrison's usable outhouse.\n\n1. Go to your Draenor Garrison and dismount. Find the outhouse appropriate to its current layout; a decorative latrine outside the usable area is not sufficient.\n\n2. For level 3 Lunarfall, search the small camp near 63,72. For level 3 Frostwall, go behind the mine toward the herb garden, around 66,92. Level 2 Frostwall has one near 55,39; level 1 Lunarfall's is behind the wagon near 50.2,38.7.\n\n3. Click the usable outhouse and wait for the interaction. The achievement and the short lighter-on-your-feet buff confirm credit.",
        stepCount = 3,
        waypoints = {
            { mapID = 582, x = 0.63, y = 0.72, step = 2, label = "Level 3 Lunarfall outhouse" },
