    [8947] = {
        achievementId = 8947,
        name = "Hurry Up, Maggot!",
        source = "Hurry Up, Maggot!",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Make the Butcher cleave six hidden maggots without reaching the lethal wound threshold.",
        acquisition = "Difficulty: Medium - Make the Butcher cleave six hidden maggots without reaching the lethal wound threshold.\n\n1. For the easier documented solo route, speak to Seer Kazal at a level 3 Garrison and choose the Walled City of Highmaul Raid Finder wing. Replies confirm this exception through Midnight despite the tooltip saying Normal or higher. The normal entrance remains a separate map reference.\n\n2. Remove reactive damage and dismiss attacking pets. Body-pull the Butcher while mounted. Use /target Maggot followed by /targetmarker 8 to find and mark each tiny maggot; the older SetRaidTarget script is protected in Midnight.\n\n3. Stand on the marked maggot and let the Butcher's cleave kill it. Repeat at all six spawns. Watch Gushing Wounds: Normal kills at five stacks, whereas the documented Raid Finder route allows more. Use his Bounding Cleave pause and distance to let stacks expire before the lethal threshold.\n\n4. After six maggots die and no further maggot spawns, kill the Butcher. On Normal, another player or a non-attacking tank pet can hold him while you move out to drop stacks; you still need to approach each maggot personally for its cleave.",
        stepCount = 4,
        waypoints = {
            { mapID = 582, x = 0.3311, y = 0.3697, step = 1, label = "Seer Kazal - Alliance Raid Finder" },
            { mapID = 590, x = 0.4146, y = 0.4719, step = 1, label = "Seer Kazal - Horde Raid Finder" },
            { mapID = 550, x = 0.32, y = 0.38, step = 4, label = "Highmaul - ordinary entrance" },
        },
        sources = {
            "https://www.wowhead.com/achievement=8947",
            "https://www.wowhead.com/achievement=8947#comments:id=2594059",
            "https://www.wowhead.com/achievement=8947#comments:id=5764933",
            "https://www.wowhead.com/achievement=8947#comments:id=5893033",
            "https://www.wowhead.com/achievement=8947#comments:id=6289475",
        },
        sourceURL = "https://www.wowhead.com/achievement=8947#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=8947",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [8948] = {
        achievementId = 8948,
        name = "Flame On!",
        source = "Flame On!",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "An immediate Kargath kill avoids destruction of pillars.",
        acquisition = "Difficulty: Easy - An immediate Kargath kill avoids destruction of pillars.\n\n1. Enter Highmaul on Normal or higher. Remove damaging procs, pets and automatic cleave when preserving enemies or waiting for a phase. \n\n2. Fight Kargath Bladefist in the opening arena. Keep him away from active Fire Pillars if a Berserker Rush begins; running him into one destroys it.\n\n3. Burst Kargath before the mechanic develops. No Fire Pillar may be destroyed during the encounter. Check the achievement after the kill.",
        stepCount = 3,
        waypoints = { { mapID = 550, x = 0.32, y = 0.38, step = 1, label = "Highmaul - Flame On!" } },
        sources = { "https://www.wowhead.com/achievement=8948" },
        sourceURL = "https://www.wowhead.com/achievement=8948#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=8948",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [8949] = {
        achievementId = 8949,
        name = "Mythic: Kargath Bladefist",
        source = "Mythic: Kargath Bladefist",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "An ordinary legacy Mythic kill; no guild or seasonal deadline.",
        acquisition = "Difficulty: Easy - An ordinary legacy Mythic kill; no guild or seasonal deadline.\n\n1. Set RAID difficulty to Mythic before entering Highmaul at the map pin. Dungeon difficulty does not select the raid's mode.\n\n2. Defeat Kargath to enter the raid. Clear the outdoor bosses and the guards outside AND inside the Twin Ogron building, then Ko'ragh to reach Imperator Mar'gok.\n\n3. Defeat Kargath Bladefist on Mythic and check the achievement. Normal, Heroic and Raid Finder kills do not replace Mythic. The retired Ahead of the Curve and Cutting Edge feats are separate records.",
        stepCount = 3,
        waypoints = { { mapID = 550, x = 0.32, y = 0.38, step = 1, label = "Highmaul - Mythic entrance" } },
        sources = { "https://www.wowhead.com/achievement=8949" },
        sourceURL = "https://www.wowhead.com/achievement=8949#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=8949",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [8952] = {
        achievementId = 8952,
        name = "Ashes, Ashes...",
        source = "Ashes, Ashes...",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Collect twenty small moving ashes in the last phase while preserving Blackhand.",
        acquisition = "Difficulty: Hard - Collect twenty small moving ashes in the last phase while preserving Blackhand.\n\n1. Enter Blackrock Foundry on Normal or higher. Remove damaging procs, pets and automatic cleave when preserving enemies or waiting for a phase. \n\n2. Remove automatic damage and carefully reach Blackhand's final, bottom platform. Bring another player to hold him away from the collector; a hunter can use a non-attacking tank pet. Stop all damage while collecting.\n\n3. Look upward for the falling orange ashes and move under them before they land. Increase particle/graphics settings if they are hard to see. Ashes can fall onto the platform: old advice requiring everyone to jump off the edge is unnecessary.\n\n4. Collect twenty total ashes during the encounter, then kill Blackhand. The short debuff does not need twenty simultaneous stacks. Keep marks and bombs away from the collecting area; if ash spawns end before twenty, reset rather than killing him and spending the attempt.",
        stepCount = 4,
        waypoints = { { mapID = 543, x = 0.516, y = 0.287, step = 1, label = "Blackrock Foundry - Ashes, Ashes..." } },
        sources = {
            "https://www.wowhead.com/achievement=8952",
            "https://www.wowhead.com/achievement=8952#comments:id=2521855",
            "https://www.wowhead.com/achievement=8952#comments:id=2532045",
            "https://www.wowhead.com/achievement=8952#comments:id=5665432",
            "https://www.wowhead.com/achievement=8952#comments:id=5853408",
            "https://www.wowhead.com/achievement=8952#comments:id=6158708",
        },
        sourceURL = "https://www.wowhead.com/achievement=8952#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=8952",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [8956] = {
        achievementId = 8956,
        name = "Mythic: Beastlord Darmac",
        source = "Mythic: Beastlord Darmac",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "An ordinary legacy Mythic kill; no guild or seasonal deadline.",
        acquisition = "Difficulty: Easy - An ordinary legacy Mythic kill; no guild or seasonal deadline.\n\n1. Set RAID difficulty to Mythic before entering Blackrock Foundry at the map pin. Dungeon difficulty does not select the raid's mode.\n\n2. Clear the three wings. Reach the Iron Maidens by the drop near Thogar's train station. For Blast Furnace, use dropped bombs on both Heat Regulators, defeat the exposed Primal Elementalists and kill the Heart of the Mountain. Complete the wings to open Blackhand's route.\n\n3. Defeat Beastlord Darmac on Mythic and check the achievement. Normal, Heroic and Raid Finder kills do not replace Mythic. The retired Ahead of the Curve and Cutting Edge feats are separate records.",
        stepCount = 3,
        waypoints = { { mapID = 543, x = 0.516, y = 0.287, step = 1, label = "Blackrock Foundry - Mythic entrance" } },
        sources = { "https://www.wowhead.com/achievement=8956" },
