    [8974] = {
        achievementId = 8974,
        name = "More Like Wrecked-us",
        source = "More Like Wrecked-us",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Wait for all eight Motes, then kill them together.",
        acquisition = "Difficulty: Easy - Wait for all eight Motes, then kill them together.\n\n1. Enter Highmaul on Normal or higher. Remove damaging procs, pets and automatic cleave when preserving enemies or waiting for a phase. \n\n2. Reduce Tectus until he performs his split; he can remain at one health while waiting for Tectonic Upheaval. Defeat both Shards to produce all eight Motes of Tectus.\n\n3. Gather all eight Motes before killing the first. Use area damage to kill all eight within one ten-second window, then allow the encounter to finish. Killing four Motes while the second Shard has not split loses the synchronized attempt.",
        stepCount = 3,
        waypoints = { { mapID = 550, x = 0.32, y = 0.38, step = 1, label = "Highmaul - More Like Wrecked-us" } },
        sources = {
            "https://www.wowhead.com/achievement=8974",
            "https://www.wowhead.com/achievement=8974#comments:id=2557377",
            "https://www.wowhead.com/achievement=8974#comments:id=3200546",
            "https://www.wowhead.com/achievement=8974#comments:id=5186823",
        },
        sourceURL = "https://www.wowhead.com/achievement=8974#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=8974",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [8975] = {
        achievementId = 8975,
        name = "A Fungus Among Us",
        source = "A Fungus Among Us",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Rapid flamethrower toggles and movement must build fifteen stacks before decay.",
        acquisition = "Difficulty: Medium - Rapid flamethrower toggles and movement must build fifteen stacks before decay.\n\n1. Enter Highmaul on Normal or higher. Remove damaging procs, pets and automatic cleave when preserving enemies or waiting for a phase. \n\n2. Pick up a BFC9000 flamethrower near Brackenspore BEFORE pulling. Body-pull without damaging him and wait until Creeping Moss covers most of the room; reducing his health to 40% is unnecessary at high level.\n\n3. Run through fresh moss while rapidly toggling the extra action button on and off. Burn several patches, turn it off immediately, then reach new patches quickly. Do not hold it continuously until it overheats. Bind the extra action button for easier repeated presses.\n\n4. Reach fifteen Burning Infusion stacks, then kill Brackenspore. Movement boosts can help counter the moss slow. If the flamethrower overheats too early, wait for cooling and more moss and try again with the boss alive. Use Normal or higher; the Raid Finder exception reported for the Butcher does not apply here.",
        stepCount = 4,
        waypoints = { { mapID = 550, x = 0.32, y = 0.38, step = 1, label = "Highmaul - A Fungus Among Us" } },
        sources = {
            "https://www.wowhead.com/achievement=8975",
            "https://www.wowhead.com/achievement=8975#comments:id=2594068",
            "https://www.wowhead.com/achievement=8975#comments:id=5986008",
            "https://www.wowhead.com/achievement=8975#comments:id=6273878",
            "https://www.wowhead.com/achievement=8975#comments:id=6293741",
            "https://www.wowhead.com/achievement=8975#comments:id=6320234",
