    },
    [8976] = {
        achievementId = 8976,
        name = "Pair Annihilation",
        source = "Pair Annihilation",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Kill Ko'ragh before fifteen unprotected orb impacts.",
        acquisition = "Difficulty: Easy - Kill Ko'ragh before fifteen unprotected orb impacts.\n\n1. Enter Highmaul on Normal or higher. Remove damaging procs, pets and automatic cleave when preserving enemies or waiting for a phase. \n\n2. Clear Ko'ragh's room to activate him, then burst him immediately. A quick legacy kill finishes before enough Overflowing Energy orbs can fail the condition.\n\n3. If fighting slowly, take a Nullification Barrier during his recharge and soak orbs with that shield; ordinary unshielded players or the ground count toward failure. Finish before fifteen invalid impacts.",
        stepCount = 3,
        waypoints = { { mapID = 550, x = 0.32, y = 0.38, step = 1, label = "Highmaul - Pair Annihilation" } },
        sources = { "https://www.wowhead.com/achievement=8976", "https://www.wowhead.com/achievement=8976#comments:id=2448532" },
        sourceURL = "https://www.wowhead.com/achievement=8976#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=8976",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [8977] = {
        achievementId = 8977,
        name = "Lineage of Power",
        source = "Lineage of Power",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Preserve one Warmage through both intermission empowerment clouds.",
        acquisition = "Difficulty: Hard - Preserve one Warmage through both intermission empowerment clouds.\n\n1. Enter Highmaul on Normal or higher. Remove damaging procs, pets and automatic cleave when preserving enemies or waiting for a phase. Mythic gives more room to control damage for this encounter.\n\n2. A Death Knight with extra Death Grip range/charges is convenient. Remove gear and automatic damage talents, including Shattering Bone, and stop auto-attacking immediately after each grip. Use controlled damage to reach the first intermission.\n\n3. Keep one Gorian Warmage alive. Move THAT SAME Warmage into the first purple cloud below Mar'gok during his channel and verify its first empowerment. A caster can also be moved gradually by standing nearby and stepping away as each cast ends.\n\n4. Lower the boss into the second intermission without killing him. Move the preserved Warmage into the other empowerment cloud and verify that it has both Fortification and Replication. Grips can trigger accidental melee swings: /stopattack and targeting yourself immediately help prevent this.\n\n5. Kill the doubly empowered Warmage, verify the tracked criterion, then kill Mar'gok after his channel. Do not replace the preserved Warmage with a fresh one from the second intermission.",
        stepCount = 5,
        waypoints = { { mapID = 550, x = 0.32, y = 0.38, step = 1, label = "Highmaul - Lineage of Power" } },
        sources = {
            "https://www.wowhead.com/achievement=8977",
            "https://www.wowhead.com/achievement=8977#comments:id=2092543",
            "https://www.wowhead.com/achievement=8977#comments:id=5881113",
            "https://www.wowhead.com/achievement=8977#comments:id=6102902",
            "https://www.wowhead.com/achievement=8977#comments:id=6154192",
            "https://www.wowhead.com/achievement=8977#comments:id=6276008",
        },
        sourceURL = "https://www.wowhead.com/achievement=8977#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=8977",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [8978] = {
        achievementId = 8978,
        name = "The Iron Price",
        source = "The Iron Price",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Use Overhead Smash to reach three suspended ores before killing Gruul.",
        acquisition = "Difficulty: Medium - Use Overhead Smash to reach three suspended ores before killing Gruul.\n\n1. Enter Blackrock Foundry on Normal or higher. Remove damaging procs, pets and automatic cleave when preserving enemies or waiting for a phase. \n\n2. Use Normal for the most consistently reported current method. Body-pull Gruul and position him by the entrance wall facing into the room. Keep him alive without automatic damage.\n\n3. Find a suspended Pristine True Iron Ore. Stand between Gruul and that ore so his Overhead Smash launches you toward it, then click the ore in the air. Slow Fall or a suitable parasol helps you click before falling. Do not wait specifically for Destructive Rampage: it can send him back to the middle.\n\n4. Repeat until three ores are credited, then kill Gruul. You can take many attempts during the same fight. A gliding character can adjust position in the air, but the required objects are the hanging Pristine ores, not Oregorger's Volatile Ore.",
        stepCount = 4,
        waypoints = { { mapID = 543, x = 0.516, y = 0.287, step = 1, label = "Blackrock Foundry - The Iron Price" } },
        sources = {
            "https://www.wowhead.com/achievement=8978",
            "https://www.wowhead.com/achievement=8978#comments:id=6277616",
            "https://www.wowhead.com/achievement=8978#comments:id=6181855",
            "https://www.wowhead.com/achievement=8978#comments:id=6416285",
        },
        sourceURL = "https://www.wowhead.com/achievement=8978#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=8978",
        reviewedAt = "2026-11-15",
