        warlordsAchievementGuide = true,
    },
    [8979] = {
        achievementId = 8979,
        name = "He Shoots, He Ores",
        source = "He Shoots, He Ores",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Carry or relay a fragile ore across Oregorger's rolling path.",
        acquisition = "Difficulty: Hard - Carry or relay a fragile ore across Oregorger's rolling path.\n\n1. Enter Blackrock Foundry on Normal or higher. Remove damaging procs, pets and automatic cleave when preserving enemies or waiting for a phase. \n\n2. Locate the Volatile Ore behind Oregorger's starting position and the Ore Grinder chute near the entrance before pulling. Body-pull and wait for his energy to drain; the special ore becomes clickable during his rolling phase.\n\n3. With a partner, pass the ore using the extra action button and catch each throw. Each holder has twenty seconds; a ground impact or rolling boss hit loses it. Clear a route through the crates, keep the boss away and deposit it in the clickable grinder during a rolling phase.\n\n4. Solo alternative: a Mage can cast Alter Time at the grinder, immediately use Shimmer plus a suitable movement boost to reach and pick up the ore, then let Alter Time return automatically. Click the grinder with the ore. Practice the route before pulling; the timer is tight and old Soulshape instructions are obsolete.\n\n5. After the successful deposit, kill Oregorger. If the ore is lost, reset the encounter with an appropriate combat reset or leave and return. Avoid changing the group during the carry. The separate floating ores above Gruul are unrelated.",
        stepCount = 5,
        waypoints = { { mapID = 543, x = 0.516, y = 0.287, step = 1, label = "Blackrock Foundry - He Shoots, He Ores" } },
        sources = {
            "https://www.wowhead.com/achievement=8979",
