    [8980] = {
        achievementId = 8980,
        name = "Stamp Stamp Revolution",
        source = "Stamp Stamp Revolution",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "An immediate kill avoids the stamping phase.",
        acquisition = "Difficulty: Easy - An immediate kill avoids the stamping phase.\n\n1. Enter Blackrock Foundry on Normal or higher. Remove damaging procs, pets and automatic cleave when preserving enemies or waiting for a phase. \n\n2. Gather Hans'gar and Franzok and kill them quickly before the stamping presses activate. Recent legacy comments confirm that skipping the phase can award credit.\n\n3. If a press phase occurs, move off every glowing floor square before the press lands and keep the entire group clear. A fast kill is preferable to historical safe-spot coordinates that replies report fixed.",
        stepCount = 3,
        waypoints = { { mapID = 543, x = 0.516, y = 0.287, step = 1, label = "Blackrock Foundry - Stamp Stamp Revolution" } },
        sources = {
