    [8981] = {
        achievementId = 8981,
        name = "Fain Would Lie Down",
        source = "Fain Would Lie Down",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Three different first mounts require three completed kills.",
        acquisition = "Difficulty: Medium - Three different first mounts require three completed kills.\n\n1. Enter Blackrock Foundry on Normal or higher. Remove damaging procs, pets and automatic cleave when preserving enemies or waiting for a phase. \n\n2. Stand beside the beast needed for the next missing criterion: Cruelfang, Ironcrusher or Dreadwing. Pull Beastlord Darmac there and deal controlled damage until he mounts that closest beast.\n\n3. Let the mounting animation finish, defeat the mounted beast, then finish Darmac. Avoid lingering in Heavy Spear targeting circles. Confirm that this first-mount criterion remains credited after the completed encounter.\n\n4. Repeat with the other two beasts on separate Normal, Heroic and Mythic runs or later resets. Do not kill him before he finishes mounting and do not reset immediately after mounting: recent reports lost that incomplete credit.",
        stepCount = 4,
        waypoints = { { mapID = 543, x = 0.516, y = 0.287, step = 1, label = "Blackrock Foundry - Fain Would Lie Down" } },
