    [8982] = {
        achievementId = 8982,
        name = "There's Always a Bigger Train",
        source = "There's Always a Bigger Train",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Two toys must be placed on a live train track in the correct order.",
        acquisition = "Difficulty: Medium - Two toys must be placed on a live train track in the correct order.\n\n1. Enter Blackrock Foundry on Normal or higher. Remove damaging procs, pets and automatic cleave when preserving enemies or waiting for a phase. \n\n2. Have Toy Train Set and Wind-Up Train Wrecker available before pulling Thogar. They are different toys; check their cooldowns before starting.\n\n3. Pull without killing him, return to the FIRST track nearest the entrance and place Toy Train Set there. Immediately place Wind-Up Train Wrecker beside it. The wrecker must destroy the toy train and become Exulting before the real train strikes it.\n\n4. Wait for the real train to run over the celebrating wrecker, then finish the boss and check credit. If timing fails, a toy cooldown can force a wait; do not use both toys in the safe walkway away from the track.",
        stepCount = 4,
        waypoints = { { mapID = 543, x = 0.516, y = 0.287, step = 1, label = "Blackrock Foundry - There's Always a Bigger Train" } },
        sources = {
            "https://www.wowhead.com/achievement=8982",
