    [8983] = {
        achievementId = 8983,
        name = "Would You Give Me a Hand?",
        source = "Would You Give Me a Hand?",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Ten characters must be grabbed simultaneously.",
        acquisition = "Difficulty: Hard - Ten characters must be grabbed simultaneously.\n\n1. Enter Blackrock Foundry on Normal or higher. Remove damaging procs, pets and automatic cleave when preserving enemies or waiting for a phase. \n\n2. Bring at least TEN characters to Kromog and remove reactive damage. Assign each a separate Rune of Grasping Earth position before pulling. Taunt from range and keep him alive until the rune phase.\n\n3. Have ten characters stand on ten different runes and WAIT until all ten hands have actually grabbed them. Empty decorative hands are not attackable substitutes; repeated phases with fewer grabbed characters do not accumulate the required ten.\n\n4. Kill the ten active hands within five seconds of the first death, then kill Kromog. A coordinated area attack handles the hands. Bring fall mitigation if needed and remain alive for credit. Reports of relogged alts are inconsistent; ten present, controlled characters are the dependable group method.",
        stepCount = 4,
        waypoints = { { mapID = 543, x = 0.516, y = 0.287, step = 1, label = "Blackrock Foundry - Would You Give Me a Hand?" } },
        sources = {
            "https://www.wowhead.com/achievement=8983",
            "https://www.wowhead.com/achievement=8983#comments:id=2518918",
            "https://www.wowhead.com/achievement=8983#comments:id=2606828",
