    [8984] = {
        achievementId = 8984,
        name = "Be Quick or Be Dead",
        source = "Be Quick or Be Dead",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Kill all three Maidens within one ten-second window.",
        acquisition = "Difficulty: Easy - Kill all three Maidens within one ten-second window.\n\n1. Enter Blackrock Foundry on Normal or higher. Remove damaging procs, pets and automatic cleave when preserving enemies or waiting for a phase. \n\n2. Reach the Iron Maidens via the drop by Thogar's train station. Gather Admiral Gar'an, Marak the Blooded and Enforcer Sorka together.\n\n3. Kill all three within ten seconds measured from the first death. At high level use a single area burst while all three are on the main platform; do not start the kill while one is away aboard the ship.",
        stepCount = 3,
        waypoints = { { mapID = 543, x = 0.516, y = 0.287, step = 1, label = "Blackrock Foundry - Be Quick or Be Dead" } },
        sources = { "https://www.wowhead.com/achievement=8984", "https://www.wowhead.com/achievement=8984#comments:id=2489752" },
        sourceURL = "https://www.wowhead.com/achievement=8984#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=8984",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [8985] = {
        achievementId = 8985,
        name = "Glory of the Draenor Raider",
        source = "Glory of the Draenor Raider",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Includes a ten-character Kromog requirement and several controlled mechanic encounters.",
        acquisition = "Difficulty: Hard - Includes a ten-character Kromog requirement and several controlled mechanic encounters.\n\n1. Use Normal or higher in Highmaul and Blackrock Foundry. Arrange at least ten characters for Would You Give Me a Hand? before planning the full run; the personal Glory meta does not require a guild group.\n\n2. In Highmaul, satisfy Kargath's intact pillars, the Butcher's six maggots, eight simultaneous Tectus Motes, fifteen Brackenspore flamethrower stacks, close Twin Ogron, Ko'ragh's orb limit and Mar'gok's doubly empowered Warmage. Open each individual guide before pulling.\n\n3. In Foundry, collect Gruul's three ores, deposit Oregorger's ore, preserve Aknor, avoid stamping presses, complete Darmac's three first mounts, run over the toy wrecker, destroy ten active Kromog hands in five seconds, kill the Maidens together, synchronize four Elementalists and collect twenty Blackhand ashes.\n\n4. Check the seventeen named criteria and repeat only missing encounters. Darmac requires multiple kills and failed mechanic attempts can spend a boss lockout. Claim the Gorestrider Gronnling after the personal meta completes; the guild Battleboar unlock is a separate achievement.",
        stepCount = 4,
        waypoints = {
            { mapID = 550, x = 0.32, y = 0.38, step = 2, label = "Highmaul - seven mechanic achievements" },
            { mapID = 543, x = 0.516, y = 0.287, step = 3, label = "Blackrock Foundry - ten mechanic achievements" },
        },
        sources = { "https://www.wowhead.com/achievement=8985" },
        sourceURL = "https://www.wowhead.com/achievement=8985#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=8985",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [8986] = {
        achievementId = 8986,
        name = "The Walled City",
        source = "The Walled City",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Kill the named wing bosses in a legacy raid.",
        acquisition = "Difficulty: Easy - Kill the named wing bosses in a legacy raid.\n\n1. Enter Highmaul at the marked entrance. Normal is a straightforward choice for these ordinary wing completions.\n\n2. Defeat Kargath to enter the raid. Clear the outdoor bosses and the guards outside AND inside the Twin Ogron building, then Ko'ragh to reach Imperator Mar'gok.\n\n3. Defeat Kargath Bladefist, The Butcher and Brackenspore. Check the individual criteria before leaving; a different wing's final boss does not fill a missing kill. These personal achievements do not require a guild group.",
        stepCount = 3,
        waypoints = { { mapID = 550, x = 0.32, y = 0.38, step = 1, label = "Highmaul - The Walled City" } },
