    [9008] = {
        achievementId = 9008,
        name = "Is Draenor on Fire?",
        source = "Is Draenor on Fire?",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Keep every Unstable Slag alive through the Gug'rokk kill.",
        acquisition = "Difficulty: Easy - Keep every Unstable Slag alive through the Gug'rokk kill.\n\n1. Select HEROIC before entering Bloodmaul Slag Mines. Several original Draenor mechanic achievements do not credit on Mythic. Remove reactive damage and damaging pets when waiting for mechanics.\n\n2. Reach Gug'rokk. Let him engage before attacking; if combining Croman's escort, wait for the follower to catch up first.\n\n3. Kill Gug'rokk quickly with single-target damage and do not kill any Unstable Slag. If a direct one-shot gives no credit, on another eligible attempt body-pull and allow a slag summon before finishing him. A reply reports an instant kill failing, so avoid damaging summons automatically.",
        stepCount = 3,
        waypoints = { { mapID = 525, x = 0.496, y = 0.247, step = 1, label = "Bloodmaul Slag Mines - entrance" } },
        sources = { "https://www.wowhead.com/achievement=9008", "https://www.wowhead.com/achievement=9008#comments:id=2580489" },
