    [9018] = {
        achievementId = 9018,
        name = "What's Your Sign?",
        source = "What's Your Sign?",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "A ranged instant kill can avoid the rune sequence.",
        acquisition = "Difficulty: Easy - A ranged instant kill can avoid the rune sequence.\n\n1. Select HEROIC before entering Shadowmoon Burial Grounds. Several original Draenor mechanic achievements do not credit on Mythic. Remove reactive damage and damaging pets when waiting for mechanics.\n\n2. Reach Sadana Bloodfury without walking over the floor runes. On Heroic, kill her from range before the mechanic develops; recent comments and replies confirm this direct method.\n\n3. If doing the full mechanic, preserve her until Dark Eclipse. Note the white runes, then run over only the purple runes between them, leaving the active lunar-cycle runes lit. Stand in an inner moon rune for Dark Eclipse, check the remaining lights and only then kill Sadana.",
        stepCount = 3,
        waypoints = { { mapID = 539, x = 0.319, y = 0.425, step = 1, label = "Shadowmoon Burial Grounds - entrance" } },
        sources = {
            "https://www.wowhead.com/achievement=9018",
