    [9023] = {
        achievementId = 9023,
        name = "...They All Fall Down",
        source = "...They All Fall Down",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Wait for twelve protectors, then kill them within three seconds.",
        acquisition = "Difficulty: Easy - Wait for twelve protectors, then kill them within three seconds.\n\n1. Select HEROIC before entering Auchindoun. Several original Draenor mechanic achievements do not credit on Mythic. Remove reactive damage and damaging pets when waiting for mechanics.\n\n2. Body-pull Soulbinder Nyami, move to a side corner away from her central position and stop attacking. Wait through repeated summon cycles until at least twelve Fallen Auchenai Protectors have gathered; this takes several minutes.\n\n3. Wait until Nyami teleports back toward the center so she is away from the adds. Kill all twelve protectors together with area damage inside three seconds, then kill Nyami. Do not kill the last needed wave immediately beside the boss.",
        stepCount = 3,
        waypoints = { { mapID = 535, x = 0.44799999999999995, y = 0.745, step = 1, label = "Auchindoun - entrance" } },
        sources = {
            "https://www.wowhead.com/achievement=9023",
