    [9024] = {
        achievementId = 9024,
        name = "This Is Why We Can't Have Nice Things",
        source = "This Is Why We Can't Have Nice Things",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Borka must smash four specific crates before either boss dies.",
        acquisition = "Difficulty: Easy - Borka must smash four specific crates before either boss dies.\n\n1. Select HEROIC before entering Grimrail Depot. Several original Draenor mechanic achievements do not credit on Mythic. Remove reactive damage and damaging pets when waiting for mechanics.\n\n2. Body-pull Rocketspark and Borka without attacking. Position behind each Priceless Paraphernalia crate relative to Borka so his Mad Dash destroys it. Use the four numbered interior pins; one crate is up on the platform.\n\n3. Visit 75.5,52.8; 73.1,33.5; 61.9,54.1; then the platform crate at 67.7,64.0. Keep Borka alive until all four break and Rocketspark complains about his things.\n\n4. Kill both bosses. If a crate animates but remains uncredited, adjust so it lies directly between Borka and you and try another dash. Replies report that formerly stuck crate fixed and confirm Heroic credit in Midnight.",
        stepCount = 4,
        waypoints = {
            { mapID = 543, x = 0.551, y = 0.318, step = 1, label = "Grimrail Depot - entrance" },
            { mapID = 606, x = 0.755, y = 0.528, step = 3, label = "Priceless crate 1" },
