    [9025] = {
        achievementId = 9025,
        name = "Icky Ichors",
        source = "Icky Ichors",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Bring twenty-five live Corpse Skitterlings to Bonemaw's Inhale.",
        acquisition = "Difficulty: Easy - Bring twenty-five live Corpse Skitterlings to Bonemaw's Inhale.\n\n1. Select HEROIC before entering Shadowmoon Burial Grounds. Several original Draenor mechanic achievements do not credit on Mythic. Remove reactive damage and damaging pets when waiting for mechanics.\n\n2. Before Bonemaw, body-pull the little Corpse Skitterlings along the route and preserve them. Gather at least twenty-five. Kill the two large worms on the bridge to activate Bonemaw without cleaving your collected spiders.\n\n3. Stand near Bonemaw to start combat, target yourself and wait. You do NOT need to lower his health. Lead the spiders into his Inhale; use the sticky puddle to keep yourself from being swallowed if possible.\n\n4. After twenty-five spiders have been sucked in, kill Bonemaw. Do not use damaging auras or pets while gathering: dead spiders do not count as fed.",
        stepCount = 4,
        waypoints = { { mapID = 539, x = 0.319, y = 0.425, step = 1, label = "Shadowmoon Burial Grounds - entrance" } },
        sources = {
