    [9026] = {
        achievementId = 9026,
        name = "Souls of the Lost",
        source = "Souls of the Lost",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Wait for Ritual of Bones, kill two skeletons together, then the boss.",
        acquisition = "Difficulty: Easy - Wait for Ritual of Bones, kill two skeletons together, then the boss.\n\n1. Select HEROIC before entering Shadowmoon Burial Grounds. Several original Draenor mechanic achievements do not credit on Mythic. Remove reactive damage and damaging pets when waiting for mechanics.\n\n2. Body-pull Ner'zhul and stop attacking. Wait for Ritual of Bones; damaging the boss is unnecessary and can kill him before the skeletons appear.\n\n3. Kill two Ritual of Bones skeletons within five seconds of the first death. Keep the area attack away from Ner'zhul, confirm the condition and then kill him.",
        stepCount = 3,
        waypoints = { { mapID = 539, x = 0.319, y = 0.425, step = 1, label = "Shadowmoon Burial Grounds - entrance" } },
