    [9056] = {
        achievementId = 9056,
        name = "Bridge Over Troubled Fire",
        source = "Bridge Over Troubled Fire",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Preserve two waves of whelps for one ten-second kill window.",
        acquisition = "Difficulty: Medium - Preserve two waves of whelps for one ten-second kill window.\n\n1. Select HEROIC before entering Upper Blackrock Spire. Several original Draenor mechanic achievements do not credit on Mythic. Remove reactive damage and damaging pets when waiting for mechanics.\n\n2. At Ragewing, remove reactive damage and force the flight phases. Modern reports say he can remain at one health while the scripted waves appear; stop attacking after triggering them.\n\n3. Preserve the first wave of ten Ragewing Whelps. Wait for the second wave and gather all twenty. A monk's Black Ox Statue can help keep the first wave from flying away.\n\n4. Kill all twenty within ten seconds, then finish Ragewing if still alive. Do not kill the first wave early or count unrelated dungeon whelps. Check Heroic difficulty before spending the encounter.",
        stepCount = 4,
        waypoints = { { mapID = 32, x = 0.35, y = 0.85, step = 1, label = "Upper Blackrock Spire - Blackrock Mountain approach" } },
        sources = {
            "https://www.wowhead.com/achievement=9056",
