    [9058] = {
        achievementId = 9058,
        name = "Leeeeeeeeeeeeeroy...?",
        source = "Leeeeeeeeeeeeeroy...?",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Revive Leeroy, clear his route and escort him after the chicken timer.",
        acquisition = "Difficulty: Medium - Revive Leeroy, clear his route and escort him after the chicken timer.\n\n1. Select HEROIC before entering Upper Blackrock Spire. Several original Draenor mechanic achievements do not credit on Mythic. Remove reactive damage and damaging pets when waiting for mechanics.\n\n2. Bring a character able to revive Leeroy, or another player with that ability. Kill Gor'ashan and Kyrak. Behind Kyrak, interact with dead Leeroy to revive him and start his chicken timer; engineering resurrection items are not a dependable substitute.\n\n3. Clear EVERY enemy on the path through Commander Tharbek to Son of the Beast, including the dog. For the most conservative route, stop before stepping onto Ragewing's bridge and leave Ragewing and Zaela alive.\n\n4. Return to Leeroy, wait until his chicken timer ends and escort him along the cleared route. Let him reach and loot Son of the Beast, finish his dialogue and leave. Check the achievement, Jenkins title and follower credit before continuing.",
        stepCount = 4,
        waypoints = { { mapID = 32, x = 0.35, y = 0.85, step = 1, label = "Upper Blackrock Spire - Blackrock Mountain approach" } },
        sources = {
