    [9071] = {
        achievementId = 9071,
        name = "Inspector Gadgetzan",
        source = "Inspector Gadgetzan",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Eight different random decoded messages from Blingtron 5000 daily gifts.",
        acquisition = "Difficulty: Hard - Eight different random decoded messages from Blingtron 5000 daily gifts.\n\n1. Find or summon BLINGTRON 5000 and claim its daily gift quest. Other Blingtron model numbers have different gift tables; do not substitute a 4000/6000/7000 gift and assume the same message pool.\n\n2. Open the gift and collect/read any Decoded Message item. Check the eight message criteria: 001-003, 001-014, 001-107, 001-111, 001-119, 001-150, 001-159 and 001-168. Duplicate messages do not fill a missing number.\n\n3. Repeat eligible daily gifts until all eight are credited. The daily Blingtron gift lockout is account-wide, so take the intended 5000 gift before another model consumes that day's opportunity. Engineering is needed to make/summon your own device, but another player's summoned 5000 can supply the gift.",
        stepCount = 3,
        waypoints = {
            { mapID = 622, x = 0.475, y = 0.405, step = 1, label = "Sean Catchpole - optional Blingtron 5000 schematic" },
            { mapID = 624, x = 0.705, y = 0.39, step = 1, label = "Nik Steelrings - optional Blingtron 5000 schematic" },
        },
