    [9076] = {
        achievementId = 9076,
        name = "Choppin' Some Logs",
        source = "Choppin' Some Logs",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Place 10 Lumber Mill work orders using gathered Timber.",
        acquisition = "Difficulty: Easy - Place 10 Lumber Mill work orders using gathered Timber.\n\n1. Build a Lumber Mill on a medium Garrison plot and finish its timber-cutting introduction. Search Draenor for highlighted timber trees appropriate to your Mill's level.\n\n2. Dismount before clicking a tree, let the lumberjack arrive and wait until Timber reaches your bags before flying away. Bring Timber back to the Lumber Mill work-order NPC.\n\n3. Place work orders until 10 are credited, collecting completed shipments to free the queue. The collection counter can combine participating characters; each still needs its own Mill and Timber. The 100-order faction variants award different titles.",
        stepCount = 3,
        waypoints = {
