    [9081] = {
        achievementId = 9081,
        name = "Expert Timing",
        source = "Expert Timing",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "One Iron Star must hit four patrolling, out-of-combat Ogron.",
        acquisition = "Difficulty: Medium - One Iron Star must hit four patrolling, out-of-combat Ogron.\n\n1. Select HEROIC before entering Iron Docks. Several original Draenor mechanic achievements do not credit on Mythic. Remove reactive damage and damaging pets when waiting for mechanics.\n\n2. Defeat Nok'gar, then approach the Iron Stars without attacking the four Ogron Laborers. Use the farthest star and watch their patrol paths until all four line up in one firing lane.\n\n3. Enter the star, aim down that lane and launch when all four are aligned and out of combat. Old Entangling Roots advice is obsolete: newer replies report root immunity.\n\n4. Check credit before spending another star. Resetting the dungeon after killing Nok'gar does not reliably restore usable stars; a failed attempt may require another eligible character or daily reset.",
        stepCount = 4,
        waypoints = { { mapID = 543, x = 0.45399999999999996, y = 0.135, step = 1, label = "Iron Docks - entrance" } },
