    [9083] = {
        achievementId = 9083,
        name = "Militaristic, Expansionist",
        source = "Militaristic, Expansionist",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Pull three named enemies and preserve them while killing Nok'gar.",
        acquisition = "Difficulty: Easy - Pull three named enemies and preserve them while killing Nok'gar.\n\n1. Select HEROIC before entering Iron Docks. Several original Draenor mechanic achievements do not credit on Mythic. Remove reactive damage and damaging pets when waiting for mechanics.\n\n2. Before attacking Fleshrender Nok'gar, identify Siegemaster Olugar, Pitwarden Gwarnok and Champion Druna. Body-pull all three into combat; do not kill or cleave them.\n\n3. Move them away from Nok'gar, then kill the boss using single-target damage while all three remain alive AND engaged. A mounted circuit to collect the nearby trash is sufficient; NPCs left idle outside combat do not satisfy the condition.",
        stepCount = 3,
        waypoints = { { mapID = 543, x = 0.45399999999999996, y = 0.135, step = 1, label = "Iron Docks - entrance" } },
