    [9094] = {
        achievementId = 9094,
        name = "Garrison Architect",
        source = "Garrison Architect",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Complete the five building and blueprint achievements.",
        acquisition = "Difficulty: Medium - Complete the five building and blueprint achievements.\n\n1. Learn twenty, forty and finally sixty different blueprints on the same purchasing character for Draftsman, Master Draftsman and Grand Master Draftsman. Building a copy of every plan is unnecessary.\n\n2. Complete Keepin' Busy by unlocking the Mine, Herb Garden, Fishing Shack and Menagerie introductions.\n\n3. Complete Master Builder by upgrading and activating three small, two medium and two large plot buildings to level 3. The four fixed preset buildings are not that plot-upgrade requirement. Check all five meta criteria and select the Architect title after completion.",
        stepCount = 3,
        waypoints = {
            { mapID = 582, x = 0.4, y = 0.37, step = 1, label = "Lunarfall - Garrison development; building plot varies" },
            { mapID = 590, x = 0.52, y = 0.5, step = 1, label = "Frostwall - Garrison development; building plot varies" },
