    [9102] = {
        achievementId = 9102,
        name = "Ashran Victory",
        source = "Ashran Victory",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Push all Road of Glory control points and defeat the opposing commander.",
        acquisition = "Difficulty: Hard - Push all Road of Glory control points and defeat the opposing commander.\n\n1. Open the PvP queue and enter Ashran. Prefer Brawl: Classic Ashran when its rotation is active for the original events, captains and rare spawns; walking into outdoor Ashran is not equivalent to entering the battleground. Check the in-game brawl calendar rather than an old posted date.\n\n2. Join the main faction push and capture every Road of Glory stage toward the enemy base. Keep the controlled stages while advancing; a normal reinforcement win elsewhere does not automatically satisfy this condition.\n\n3. Kill the enemy commander while your faction controls all required road points. Classic Ashran avoids the ordinary match ending before the full push, as confirmed in later replies. Check the achievement after the commander dies.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 588 },
        sources = { "https://www.wowhead.com/achievement=9102", "https://www.wowhead.com/achievement=9102#comments:id=5552164" },
        sourceURL = "https://www.wowhead.com/achievement=9102#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=9102",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [9103] = {
        achievementId = 9103,
        name = "Bounty Hunter",
        source = "Bounty Hunter",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Loot seven different racial trophies; enemy race availability and drops vary.",
        acquisition = "Difficulty: Hard - Loot seven different racial trophies; enemy race availability and drops vary.\n\n1. Use a Horde character. Open the PvP queue and enter Ashran. Prefer Brawl: Classic Ashran when its rotation is active for the original events, captains and rare spawns; walking into outdoor Ashran is not equivalent to entering the battleground. Check the in-game brawl calendar rather than an old posted date.\n\n2. After qualifying enemy-player deaths, interact with the corpse to remove its insignia and loot any racial trophy. You need trophies from Pandaren, Night Elf, Gnome, Draenei, Worgen, Dwarf and Human. Merely receiving an honorable kill does not guarantee the item.\n\n3. Track the missing race criteria and loot those races' corpses whenever possible. These are random drops; modern reports confirm they still drop and that the earlier Worgen-snount problem was later resolved. Do not use obsolete class-trial outdoor-Ashran methods that current replies say teleport participants out.\n\n4. Keep looting across matches until every required trophy is credited, then turn spare trophy quests in at your base for reputation. Related allied races are not a universal substitution: inspect actual trophy/criterion credit instead of assuming a matching model counts.",
        stepCount = 4,
        waypoints = {},
