    [9107] = {
        achievementId = 9107,
        name = "Follow the Leader",
        source = "Follow the Leader",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Recruit 5 followers; additional Inn recruitment is weekly.",
        acquisition = "Difficulty: Easy - Recruit 5 followers; additional Inn recruitment is weekly.\n\n1. Complete Draenor story and follower-rescue quests and accept their follower rewards. Open the Garrison follower list to distinguish actual recruits from merely meeting an NPC.\n\n2. Build a level 2 Lunarfall Inn/Frostwall Tavern and speak to its headhunter for one new follower per weekly recruitment opportunity. Named quest/reputation recruits and weekly Inn recruits build the roster; the active mission cap is not a permanent limit on recruitment.\n\n3. Reach 5 credited recruits. If above the active cap, deactivate spare followers before sending missions. Commander is the forty-recruit achievement's name; it does not award a Commander character title.",
        stepCount = 3,
        waypoints = {
            {
                mapID = 582,
                x = 0.4,
                y = 0.37,
                step = 2,
                label = "Lunarfall - Inn/Tavern headhunter and follower table; building plot varies",
            },
            {
                mapID = 590,
                x = 0.52,
