    [9139] = {
        achievementId = 9139,
        name = "On a Massive Number of Missions",
        source = "On a Massive Number of Missions",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Successfully complete 500 time-gated Garrison missions.",
        acquisition = "Difficulty: Hard - Successfully complete 500 time-gated Garrison missions.\n\n1. Open the Garrison mission table and assign followers whose abilities counter each mission's threats. Use short high-success missions while playing and longer ones before logging out.\n\n2. Return after the timers finish and claim the rewards. A failed mission does not add a successful completion; simply dispatching followers is insufficient.\n\n3. Continue until 500 successful missions are credited. Keep the table supplied with Garrison Resources and use enough followers to run several missions at once. Naval missions have also been reported to contribute, but monitor the live counter rather than adding old character totals yourself.",
        stepCount = 3,
        waypoints = {
            { mapID = 582, x = 0.4, y = 0.37, step = 1, label = "Lunarfall - Garrison mission table; building plot varies" },
            { mapID = 590, x = 0.52, y = 0.5, step = 1, label = "Frostwall - Garrison mission table; building plot varies" },
