    [9150] = {
        achievementId = 9150,
        name = "Exploration Mission Specialist",
        source = "Exploration Mission Specialist",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Exploration mission offers are random and repeatable.",
        acquisition = "Difficulty: Medium - Exploration mission offers are random and repeatable.\n\n1. Train at least basic Archaeology on a character with an unlocked Garrison mission table. Develop followers able to succeed at the missions. You do not need the old maximum Archaeology skill just to see offers.\n\n2. Check for Exploration missions naturally, including on your Archaeology-trained alts. Optional acceleration: buy Explorer's Notebook for five Restored Artifacts at the Archaeology vendor in Stormshield/Warspear and use it to generate an eligible mission. The old Pandaria Spirit of Harmony-to-Restored Artifact exchange was removed.\n\n3. Complete the offered mission successfully and claim it. One successful Exploration mission is sufficient; not every archaeology-reward mission has the required mission category.\n\n4. Complete existing Exploration offers to allow later ones to appear. Use Exploration Mission Master separately if you want the full named checklist.",
        stepCount = 4,
        waypoints = {
            { mapID = 582, x = 0.4, y = 0.37, step = 1, label = "Lunarfall - Exploration mission table" },
            { mapID = 590, x = 0.52, y = 0.5, step = 1, label = "Frostwall - Exploration mission table" },
            { mapID = 622, x = 0.483, y = 0.332, step = 2, label = "Stormshield - Archaeology vendor area" },
            { mapID = 624, x = 0.746, y = 0.318, step = 2, label = "Warspear - Archaeology vendor area" },
        },
        sources = {
            "https://www.wowhead.com/achievement=9150",
            "https://www.wowhead.com/achievement=9150#comments:id=2093465",
            "https://www.wowhead.com/achievement=9150#comments:id=5823152",
