    [9255] = {
        achievementId = 9255,
        name = "Mythic Draenor Raider",
        source = "Mythic Draenor Raider",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Clear all seventeen bosses of two legacy Mythic raids.",
        acquisition = "Difficulty: Easy - Clear all seventeen bosses of two legacy Mythic raids.\n\n1. Select Mythic RAID difficulty and clear all seven Highmaul encounters, including optional The Butcher, Brackenspore and Tectus. Defeat all phases of Imperator Mar'gok.\n\n2. Clear all ten Blackrock Foundry encounters on Mythic, including Blast Furnace and the Iron Maidens. Finish Blackhand after completing the three wings.\n\n3. Check the seventeen personal Mythic achievements. Hellfire Citadel and guild-run criteria are not part of this monument meta. Recent replies report the achievement completing while its Garrison monument remains unavailable; do not promise the monument display as proof of completion.",
        stepCount = 3,
        waypoints = {
            { mapID = 550, x = 0.32, y = 0.38, step = 1, label = "Highmaul - all seven Mythic encounters" },
            { mapID = 543, x = 0.516, y = 0.287, step = 2, label = "Blackrock Foundry - all ten Mythic encounters" },
