    [9264] = {
        achievementId = 9264,
        name = "Draenor Pet Brawler",
        source = "Draenor Pet Brawler",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Win 2000 full pet battles in Draenor.",
        acquisition = "Difficulty: Hard - Win 2000 full pet battles in Draenor.\n\n1. Prepare healthy level-25 pets, bandages and family counters, then battle wild pets in the six Draenor zones. Collect missing Safari species while adding wins; character combat kills do not count as pet-battle victories.\n\n2. For focused repetition, choose dense wild populations near your Garrison or Frostfire's Icespine Hatchlings and finish the complete opposing team. A capture counts when you win the rest of the battle; forfeiting does not replace a win.\n\n3. Tanaan's legendary pet battles also advance Draenor Pet Brawler according to comments. Repeating suitable battles can continue the win grind even when their daily bag was already earned; heal between fights and watch the actual counter.\n\n4. Reach 2000 total wins. The achievement and monument display are separate: a missing monument-selection option does not prove that the battle counter failed.",
        stepCount = 4,
        waypoints = { { mapID = 525, x = 0.6233, y = 0.3225, step = 2, label = "Icespine Hatchlings - wild battle search" } },
