    [9401] = {
        achievementId = 9401,
        name = "Shredder Maniac",
        source = "Shredder Maniac",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Requires the Lumber Yard outpost ability and fifty looted thornvine treasures.",
        acquisition = "Difficulty: Medium - Requires the Lumber Yard outpost ability and fifty looted thornvine treasures.\n\n1. Choose the Lumber Yard at your Gorgrond outpost to obtain the Mechashredder 5000 zone ability. This is NOT the Lumber Mill in your Garrison. If you chose the Arena, finish the outpost story and use the outpost building-switch NPC; older comments saying the choice is permanent are obsolete.\n\n2. Visit the marked Hardened Thornvine locations across Gorgrond, including inside the three marked caves. Dismount first, summon/use your shredder, and cut the vines. A current Midnight comment reports disconnects when clicking while mounted.\n\n3. Leave the vehicle before looting the treasure revealed beneath each vine. Cutting alone does not count. Collect fifty treasures, revisiting replenished locations; do not remain inside the shredder while looting.",
        stepCount = 3,
        waypoints = {
            { mapID = 543, x = 0.528, y = 0.599, step = 1, label = "Alliance outpost - building choice" },
            { mapID = 543, x = 0.462, y = 0.696, step = 1, label = "Horde outpost - building choice" },
