    [9405] = {
        achievementId = 9405,
        name = "Working Some Orders",
        source = "Working Some Orders",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Repeated timed Garrison work orders; several buildings can run queues together.",
        acquisition = "Difficulty: Medium - Repeated timed Garrison work orders; several buildings can run queues together.\n\n1. Construct small profession buildings such as the Forge, Tailoring Emporium or Enchanter's Study. Complete each building's introductory work-order quest and provide the Draenor materials shown by its work-order NPC.\n\n2. Fill the queues in each available profession building, return after production and collect the completed shipments. Reach 125 completed work orders in total. Keep multiple queues running to reduce elapsed time; placing an order and completing it are different stages.\n\n3. Use profession-building shipments as the reliable source: old comments disagree about whether preset mine/garden orders advance the displayed total. Watch actual achievement progress after collecting. At 250, level 3 profession-building blueprints unlock, but purchasing/building them still requires a tier 3 Garrison.",
        stepCount = 3,
        waypoints = {
            {
                mapID = 582,
