    [9408] = {
        achievementId = 9408,
        name = "Operation Counterattack",
        source = "Operation Counterattack",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Defeat the enemy summoned champion within eight minutes of its summon.",
        acquisition = "Difficulty: Hard - Defeat the enemy summoned champion within eight minutes of its summon.\n\n1. Open the PvP queue and enter Ashran. Prefer Brawl: Classic Ashran when its rotation is active for the original events, captains and rare spawns; walking into outdoor Ashran is not equivalent to entering the battleground. Check the in-game brawl calendar rather than an old posted date.\n\n2. Watch for the Horde summoning Kronus. Rally your faction's group immediately and intercept that champion on its route from the opposing base.\n\n3. Defeat Kronus within EIGHT minutes of the summon announcement, staying with the credited group for the kill. The timer is not eight minutes from when you personally first engage it. If the deadline passes, wait for another summon rather than assuming a later kill qualifies.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 588 },
        sources = { "https://www.wowhead.com/achievement=9408", "https://www.wowhead.com/achievement=9217#comments:id=2098092" },
