        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [9423] = {
        achievementId = 9423,
        name = "Goliaths of Gorgrond",
        source = "Goliaths of Gorgrond",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Defeat two alternating outdoor world bosses; normally requires two weeks.",
        acquisition = "Difficulty: Easy - Defeat two alternating outdoor world bosses; normally requires two weeks.\n\n1. Go to the Gorgrond world-boss area around 44,40 and check which boss is present. Drov the Ruiner and Tarlna the Ageless alternate by weekly reset; killing one repeatedly cannot award the other's criterion.\n\n2. Defeat the currently available boss and check its criterion. Avoid the large telegraphed ground attacks; a developed Retail character can handle the legacy fight, or join another player already fighting it.\n\n3. Return after the weekly rotation changes and defeat the other named boss. Both credited kills complete the achievement; loot or a particular dropped item is not required.",
        stepCount = 3,
        waypoints = { { mapID = 543, x = 0.44, y = 0.4, step = 1, label = "Drov / Tarlna - alternating world-boss area" } },
        sources = { "https://www.wowhead.com/achievement=9423", "https://www.wowhead.com/achievement=9423#comments:id=2056662" },
        sourceURL = "https://www.wowhead.com/achievement=9423#comments",
