        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [9425] = {
        achievementId = 9425,
        name = "So Grossly Incandescent",
        source = "So Grossly Incandescent",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Defeat the legacy outdoor world boss Rukhmar.",
        acquisition = "Difficulty: Easy - Defeat the legacy outdoor world boss Rukhmar.\n\n1. Go to Draenor Spires of Arak's western coast around 36.4,39. Rukhmar patrols in the air; search above the coast rather than entering Skyreach.\n\n2. Wait for her patrol / respawn, tag and defeat Rukhmar. If other players are waiting, allow them time to tag rather than immediately killing her from maximum range.\n\n3. Check the kill criterion. Solar Spirehawk is a separate rare mount drop and is not needed for this achievement; bonus rolls cannot produce that mount.",
        stepCount = 3,
        waypoints = { { mapID = 542, x = 0.364, y = 0.39, step = 1, label = "Rukhmar - aerial patrol reference" } },
        sources = { "https://www.wowhead.com/achievement=9425", "https://www.wowhead.com/achievement=9425#comments:id=2858973" },
        sourceURL = "https://www.wowhead.com/achievement=9425#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=9425",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [9429] = {
        achievementId = 9429,
        name = "Upgrading the Mill",
        source = "Upgrading the Mill",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Seventy-five Lumber Mill orders plus two separate quest requirements.",
        acquisition = "Difficulty: Medium - Seventy-five Lumber Mill orders plus two separate quest requirements.\n\n1. Build and upgrade the Garrison Lumber Mill to level 2, collect Timber outdoors, and place seventy-five Lumber Mill work orders. This is separate from the Gorgrond Lumber Yard outpost. Merely finishing the two quests does not replace the work-order count.\n\n2. Find a Petrified Ancient with dead peons around it and attempt to harvest it. Kill the awakened tree and loot the quest-starting item for Legacy of the Ancients (36385). While that quest is active, harvest MEDIUM Timber in Shadowmoon Valley, Gorgrond, Spires of Arak and Nagrand to summon and defeat each required ancient. Small Timber does not summon them; finish each fight before leaving.\n\n3. Find a Fallen Tree/Lumber node containing the trapped Barov follower and cut it open. Return to your Lumber Mill for Reduction in Force (36448 Alliance / 36449 Horde), find and defeat the rival Barov at the quest's indicated Timber node, and turn in his head.\n\n4. Confirm both quest criteria and seventy-five orders. Upgrade the Town Hall to level 3 if necessary, then buy and learn the level 3 Lumber Mill blueprint from the Garrison blueprint vendor. Later comments confirm that a completed achievement alone does not bypass the Town Hall requirement.",
        stepCount = 4,
        waypoints = {
            { mapID = 582, x = 0.4, y = 0.37, step = 1, label = "Lunarfall - Lumber Mill; building plot varies" },
            { mapID = 590, x = 0.52, y = 0.5, step = 1, label = "Frostwall - Lumber Mill; building plot varies" },
        },
        areaMaps = { 539, 543, 542, 550 },
        sources = {
