    [9434] = {
        achievementId = 9434,
        name = "One of Us! One of Us!",
        source = "One of Us! One of Us!",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Reach ten Void Essence stacks within the void realm.",
        acquisition = "Difficulty: Easy - Reach ten Void Essence stacks within the void realm.\n\n1. Enter an active purple void portal at the Shadowmoon Enclave, northeastern Spires of Arak. This is the alternate void realm, not simply the normal assault area.\n\n2. Stay within a protective reality bubble and kill void enemies for Void Essence. Packs of small fragments/remnants are a quick source; kill enough to reach ten stacks.\n\n3. Ten stacks trigger Power Overwhelming and the transformation, awarding the achievement. Do not travel between bubbles until the outside-void timer expires: it can eject you. Kenos and a three-player summon are unnecessary for this transformation achievement.",
        stepCount = 3,
        waypoints = { { mapID = 542, x = 0.7227, y = 0.23620000000000002, step = 1, label = "One of Us! One of Us! - activity area" } },
