    [9435] = {
        achievementId = 9435,
        name = "Take From Them Everything",
        source = "Take From Them Everything",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Maintain a supply buff for ten uninterrupted minutes.",
        acquisition = "Difficulty: Easy - Maintain a supply buff for ten uninterrupted minutes.\n\n1. Accept the Socrethar's Rise assault or its missive before visiting the Sargerei supply area in Draenor Shadowmoon Valley. Scout nearby fruit baskets around 48,72.7 and 50,74.\n\n2. Use a basket to gain its beneficial effect. Refresh the SAME effect from another basket shortly before expiry, repeating until you have maintained it for ten continuous minutes. Check the name so you do not confuse fruit baskets and gem baskets.\n\n3. Stay inside Socrethar's Rise for the full ten minutes, including after the last refresh. Flying away removes the buff and resets the uninterrupted attempt. Finish the assault after the achievement.",
        stepCount = 3,
        waypoints = {
            { mapID = 539, x = 0.48, y = 0.727, step = 1, label = "Take From Them Everything - activity area" },
            { mapID = 539, x = 0.5, y = 0.74, step = 2, label = "Supply baskets - refresh the same buff" },
        },
