    [9437] = {
        achievementId = 9437,
        name = "A Demidos of Reality",
        source = "A Demidos of Reality",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Find and kill one rare on the Socrethar's Rise hill.",
        acquisition = "Difficulty: Easy - Find and kill one rare on the Socrethar's Rise hill.\n\n1. Travel to Demidos's rocky hill in Socrethar's Rise, Draenor Shadowmoon Valley. Fly to the summit, or use the climb beginning around 47.19,73.36 if travelling on the ground.\n\n2. Find and defeat Demidos, Devourer of Lights. If absent, wait or revisit his spawn; ordinary void creatures nearby do not count.\n\n3. Check achievement credit after the kill. The Servant of Demidos pet is a separate random drop and is not required for this achievement.",
        stepCount = 3,
        waypoints = {
            { mapID = 539, x = 0.46, y = 0.718, step = 1, label = "A Demidos of Reality - activity area" },
