    [9468] = {
        achievementId = 9468,
        name = "Salvaging Pays Off",
        source = "Salvaging Pays Off",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Unlock the Salvage Yard, then open one hundred mission-generated salvage containers.",
        acquisition = "Difficulty: Medium - Unlock the Salvage Yard, then open one hundred mission-generated salvage containers.\n\n1. Complete the Pinchwhistle questline in southern Spires of Arak to unlock the Salvage Yard blueprint. Start at Pinchwhistle Point and follow the story through Pinchwhistle Gearworks; arriving at the final camp without its preceding quests can leave it empty.\n\n2. Build a Salvage Yard in a small Garrison plot. Send followers on frequent short, successful missions and collect the resulting Bags/Crates of Salvage. The Salvage Yard must be present for the corresponding mission salvage rewards.\n\n3. Open one hundred salvage containers. The count is pieces of salvage OPENED, not individual contents or the number of missions sent. Upgrade to level 2 when available and continue until the level 3 blueprint unlocks; the Garrison's Town Hall must also support level 3 construction.",
        stepCount = 3,
        waypoints = {
