    [9469] = {
        achievementId = 9469,
        name = "Arakkoa Outcasts",
        source = "Arakkoa Outcasts",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Repeatable reputation farming to Exalted; combat is simple at high level.",
        acquisition = "Difficulty: Medium - Repeatable reputation farming to Exalted; combat is simple at high level.\n\n1. Open the reputation panel and select Arakkoa Outcasts. Check this character's standing before beginning so you know the remaining grind and have the correct faction.\n\n2. Complete the arakkoa story quests in Talador and Spires of Arak, then farm hostile creatures around Lost Veil Anzu. Amorphic Cognitors occur in small clusters and give repeatable kill reputation. Relic of Rukhmar mission tokens, Medallions of the Legion and Warlords Timewalking commendations are alternatives.\n\n3. Continue until the panel shows EXALTED and check the achievement. Do not confuse this with a Revered-only Pathfinder requirement. A level 3 Trading Post's Draenor reputation bonus can shorten later grinds; token prices and availability should be checked before spending badges or gold.",
        stepCount = 3,
        waypoints = { { mapID = 542, x = 0.73, y = 0.45, step = 2, label = "Arakkoa Outcasts - farming / hand-in area" } },
