    [9486] = {
        achievementId = 9486,
        name = "Goodness Gracious",
        source = "Goodness Gracious",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Run over twelve distinct rune centers within six seconds.",
        acquisition = "Difficulty: Medium - Run over twelve distinct rune centers within six seconds.\n\n1. Reach the upper residential building at 34.6,46.2 in Shattrath, Talador. Fly up or use the nearby elevator. Go inside and identify the center rune and the ring of surrounding runes.\n\n2. Practice the route, then begin on the MIDDLE rune and sweep the outer ring. Use a controllable movement boost such as Burning Rush, Hover, Angelic Feather or a speed potion. Step through each rune's center so it visibly activates.\n\n3. Activate twelve DIFFERENT runes within six seconds and remain alive. Excessive speed can skip triggers; immunity effects or mount-like movement can also prevent activation. If it fails, let the runes reset and repeat the center-first route rather than circling already-active runes.",
        stepCount = 3,
        waypoints = { { mapID = 535, x = 0.34600000000000003, y = 0.462, step = 1, label = "Goodness Gracious - activity area" } },
