    [9487] = {
        achievementId = 9487,
        name = "Got My Mind On My Draenor Money",
        source = "Got My Mind On My Draenor Money",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Loot ten thousand gold in eligible Draenor areas; quest gold is different.",
        acquisition = "Difficulty: Medium - Loot ten thousand gold in eligible Draenor areas; quest gold is different.\n\n1. Track this achievement's gold counter, then run Draenor dungeons or Highmaul/Blackrock Foundry and loot the corpses. Iron Docks is a practical repeated dungeon route. Quest rewards, selling items and Auction House proceeds do not replace looted gold.\n\n2. Repeat eligible clears until the counter reaches 10,000 gold, checking the change after a run. The original reduction to 2,500 was later reversed; use the current 10,000 requirement.\n\n3. Do not buy Savage Blood gold bags based on the old popular shortcut: later reports say those bags stopped counting. Hellfire Citadel gold has also been reported excluded. If using a gold container obtained elsewhere, confirm one opened in Draenor advances the counter before spending time collecting more.",
        stepCount = 3,
        waypoints = {
            { mapID = 543, x = 0.45399999999999996, y = 0.135, step = 1, label = "Iron Docks - repeatable dungeon entrance" },
            { mapID = 543, x = 0.516, y = 0.287, step = 1, label = "Blackrock Foundry - raid entrance" },
            { mapID = 550, x = 0.32, y = 0.38, step = 1, label = "Highmaul - raid entrance" },
        },
        sources = {
