    [9497] = {
        achievementId = 9497,
        name = "Finding Your Waystones",
        source = "Finding Your Waystones",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Build the portal building before farming five hundred ogre drops.",
        acquisition = "Difficulty: Medium - Build the portal building before farming five hundred ogre drops.\n\n1. Build a Mage Tower (Alliance) or Spirit Lodge (Horde) in a large Garrison plot and finish its introduction. Without this building, do not expect Ogre Waystones to drop simply because you kill the listed ogres.\n\n2. Farm ogres at Kor'gall's Hovel/Stonemaul Arena in Gorgrond, around 39,66, or the Grimfrost Hill camp at Frostfire Ridge 66,46. Loot every kill. A 2024 comparative comment recommends checking actual drops/respawns rather than treating every old 'best spot' claim as current.\n\n3. Loot five hundred Ogre Waystones in total. The old sixty-stone cap was increased; do not follow obsolete instructions to delete stones or repeatedly close portals. Use your missing count to decide whether another circuit is needed.",
        stepCount = 3,
        waypoints = {
            { mapID = 543, x = 0.39, y = 0.66, step = 2, label = "Kor'gall's Hovel / Stonemaul Arena" },
