    [9528] = {
        achievementId = 9528,
        name = "On the Shadow's Trail",
        source = "On the Shadow's Trail",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "A short optional story chain separate from the main zone Loremaster chapters.",
        acquisition = "Difficulty: Easy - A short optional story chain separate from the main zone Loremaster chapters.\n\n1. Use a Alliance character. Take Meet Us at Starfall Outpost from the Lunarfall Town Hall when eligible, then meet Khadgar at Starfall Outpost in Shadowmoon Valley. The breadcrumb can be skipped if Catching His Eye is already available there.\n\n2. Complete Catching His Eye, Shrouding Stones and Ominous Portents. Collect the requested summoning soul shards, then finish Heart On Fire and Forging the Soul Trap. Accept each follow-up before collecting its quest-specific items.\n\n3. Finish To Catch a Shadow and its final hand-in. The character quest route shows the next unfinished stage and live quest objectives after acceptance. Another character's account achievement does not imply this one has completed Khadgar's errands.",
        stepCount = 3,
        waypoints = { { mapID = 539, x = 0.292, y = 0.256, step = 1, label = "Khadgar's optional chain - outpost reference" } },
        areaMaps = { 539 },
        sources = { "https://www.wowhead.com/achievement=9528", "https://www.wowhead.com/achievement=9528#comments:id=1992933" },
