    [9533] = {
        achievementId = 9533,
        name = "Breaker of Chains",
        source = "Breaker of Chains",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Repeatedly free frozen prisoners; an assault is unnecessary for those prisoners.",
        acquisition = "Difficulty: Easy - Repeatedly free frozen prisoners; an assault is unnecessary for those prisoners.\n\n1. Visit Stonefury Cliffs and break the ice around Frozen Slaves at 40,20. Your own attacks should break the ice; do not rely on a pet's finishing blow.\n\n2. Alternate with the nearby cluster at 38,17.7 while the first prisoners respawn. Free fifty prisoners in total. Frozen prisoners count without the assault missive, as confirmed by later comments and replies correcting the older daily-only advice.\n\n3. If also opening cages or shackles, accept the Stonefury Cliffs assault/missive, kill guards for keys and use them on the prisoners. Those extra interactions can accelerate the total, but are optional for the frozen-prisoner method.",
        stepCount = 3,
        waypoints = {
            { mapID = 525, x = 0.4, y = 0.2, step = 1, label = "Breaker of Chains - activity area" },
