    [9534] = {
        achievementId = 9534,
        name = "Delectable Ogre Delicacies",
        source = "Delectable Ogre Delicacies",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Three food buffs must overlap before their short durations expire.",
        acquisition = "Difficulty: Medium - Three food buffs must overlap before their short durations expire.\n\n1. Accept Assault on Stonefury Cliffs from your Garrison or a missive and keep it unfinished. Search Bloodmaul Stronghold's huts and tables for Toasted Roach Crunchies, Pickled Rat Skewers and Charred Boar Chops.\n\n2. Scout all three foods BEFORE consuming any. Check the building near 48,15 and the stone table across from it, with alternatives around 44.21,15.05 and 39.52,19.79. Look inside fire pits and pillars where an object may be partly hidden.\n\n3. Use the Roach Crunchies first because its buff lasts longer, then quickly right-click the Skewers and Chops. All three well-fed effects must overlap. If one is missing, wait for respawns and scout again instead of wasting the two-minute buffs.",
        stepCount = 3,
        waypoints = {
            { mapID = 525, x = 0.48, y = 0.15, step = 1, label = "Delectable Ogre Delicacies - activity area" },
