    [9535] = {
        achievementId = 9535,
        name = "That Was Entirely Unnecessary",
        source = "That Was Entirely Unnecessary",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Punt one hundred Acidmaw Eggs during the Magnarok assault.",
        acquisition = "Difficulty: Easy - Punt one hundred Acidmaw Eggs during the Magnarok assault.\n\n1. Buy/use the Magnarok scouting missive from your Garrison quartermaster, or accept Assault on Magnarok from the table. The eggs are only interactable while the assault is active.\n\n2. Search the lava pools around Magnarok, particularly 72.67,22.64. Right-click the small grey Acidmaw Eggs on the lava rocks to punt them. Their name is Acidmaw Egg, not necessarily Goren Egg.\n\n3. Continue to one hundred credited punts, revisiting respawns as needed. The counter persists across visits; finishing an assault early means taking another eligible assault later rather than restarting the whole achievement.",
        stepCount = 3,
        waypoints = {
            { mapID = 525, x = 0.71, y = 0.26, step = 1, label = "That Was Entirely Unnecessary - activity area" },
            { mapID = 525, x = 0.7267, y = 0.22640000000000002, step = 2, label = "Acidmaw Egg pools" },
        },
