    [9536] = {
        achievementId = 9536,
        name = "Slagnarok",
        source = "Slagnarok",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Slag enemies with a ridden Acidmaw before killing them.",
        acquisition = "Difficulty: Easy - Slag enemies with a ridden Acidmaw before killing them.\n\n1. Enter Magnarok in Frostfire Ridge. Find a rolling Vicious Acidmaw and interact to ride it as a vehicle.\n\n2. Roll through groups of nearby creatures, especially the small clustered targets, until they receive the Slagged debuff from its acid. Do not kill them before applying it.\n\n3. Dismount and defeat the slagged enemies, repeating until twenty are credited. The hillside near Firaga has both Acidmaws and useful packs. This does not require completing the Magnarok assault first.",
        stepCount = 3,
        waypoints = {
            { mapID = 525, x = 0.6726000000000001, y = 0.3654, step = 1, label = "Slagnarok - activity area" },
            { mapID = 525, x = 0.75, y = 0.3, step = 2, label = "Firaga hillside - Acidmaws and packs" },
