    [9537] = {
        achievementId = 9537,
        name = "By Fire Be... Merged?",
        source = "By Fire Be... Merged?",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Return Firaga's essence without using a Kindling Flame.",
        acquisition = "Difficulty: Easy - Return Firaga's essence without using a Kindling Flame.\n\n1. Accept Assault on Magnarok or its missive and keep it active, then take Rekindling an Old Flame (37204) from Firaga at the back of Magnarok.\n\n2. Follow the quest marker up to the Essence of Flame and pick it up. Return to Firaga without clicking any Kindling Flame along the route. Movement tools can shorten the return; avoid tornadoes and unnecessary combat.\n\n3. Approach Firaga and finish the quest. Comments repeatedly report credit even when mounting drops the visible essence or its bar expires, provided no Kindling Flame was used; do not rekindle it as a reaction to the warning.",
        stepCount = 3,
        waypoints = { { mapID = 525, x = 0.75, y = 0.3, step = 1, label = "By Fire Be... Merged? - activity area" } },
