    [9541] = {
        achievementId = 9541,
        name = "The Song of Silence",
        source = "The Song of Silence",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Two ordinary rares and two horn-summoned targets.",
        acquisition = "Difficulty: Medium - Two ordinary rares and two horn-summoned targets.\n\n1. Take Assault on Mok'gol Watchpost or its missive. Kill Brutag Grimblade around 43,36.2 and Karosh Blackwind around 45.9,34.7 when available.\n\n2. Kill Mok'gol Pack-Leaders until Secret Meeting Details drops. Use the Signal Horn around 42.6,36.2 with those details to bring out Krahl Deadeye and Gortag Steelgrip.\n\n3. Defeat both summoned targets and check all four criteria. Keep the assault available until any required interactions are finished; revisit empty spawns rather than treating the two horn targets as ordinary always-present rares.",
        stepCount = 3,
        waypoints = {
            { mapID = 550, x = 0.43, y = 0.36200000000000004, step = 1, label = "The Song of Silence - activity area" },
            { mapID = 550, x = 0.45899999999999996, y = 0.34700000000000003, step = 1, label = "Karosh Blackwind" },
