    [9543] = {
        achievementId = 9543,
        name = "Invasion? What Invasion?",
        source = "Invasion? What Invasion?",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Repeated full-length defense events make this a lengthy grind.",
        acquisition = "Difficulty: Hard - Repeated full-length defense events make this a lengthy grind.\n\n1. Use a level 3 Draenor Garrison. Buy an appropriate Scouting Missive for 200 Garrison Resources from Sergeant Crowler (Alliance) or Sergeant Grimjaw (Horde), complete its assault with kills and turn it in. If an invasion does not appear, repeat the corresponding assault/kills: invasion threat is not a guaranteed one-kill trigger.\n\n2. Return to the Garrison and speak to its sergeant to start the invasion. Invite up to two helpers and have them enter the leader's Garrison first. Cover the entrances, kill attackers promptly, rescue frightened citizens, intercept saboteurs/snipers and defend buildings until the final boss and cleanup finish. Finish 50 invasions in total; watch the achievement counter after each. Use a level 3 Garrison when hosting, because lower-tier defenses have been reported not to advance this counter.\n\n3. Repeat missives or join other eligible Garrison defenses. The weekly loot limit does not impose a one-invasion-per-week achievement limit. Later replies correct the old claim that guards alone always finish the defense: assist with attackers and special events.",
        stepCount = 3,
        waypoints = {
            { mapID = 582, x = 0.4, y = 0.37, step = 1, label = "Lunarfall - invasion sergeant; building plot varies" },
            { mapID = 590, x = 0.52, y = 0.5, step = 1, label = "Frostwall - invasion sergeant; building plot varies" },
        },
        sources = {
            "https://www.wowhead.com/achievement=9543",
            "https://www.wowhead.com/achievement=9543#comments:id=2308988",
            "https://www.wowhead.com/achievement=9543#comments:id=5819906",
        },
