        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [9545] = {
        achievementId = 9545,
        name = "More Plots",
        source = "More Plots",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Gather the upgrade resources and finish the Town Hall upgrade on this character.",
        acquisition = "Difficulty: Medium - Gather the upgrade resources and finish the Town Hall upgrade on this character.\n\n1. Use a Horde character with its own Garrison. Open the Architect Table and select the TOWN HALL rather than an individual small, medium or large building.\n\n2. Choose the level 2 Garrison upgrade and read its current level, gold and Garrison Resource requirements. Complete the offered Bigger is Better/My Very Own Castle upgrade quest when available; the original expansion's level 92/100 numbers are obsolete after level squishes.\n\n3. Supply the displayed cost, complete the upgrade and enter the finished layout. Level 2 supplies additional building plots and opens the preset-building introductions.",
