    [9552] = {
        achievementId = 9552,
        name = "No Tag-backs!",
        source = "No Tag-backs!",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Two players must keep Curtain of Flame bouncing through the route to Teron'gor.",
        acquisition = "Difficulty: Medium - Two players must keep Curtain of Flame bouncing through the route to Teron'gor.\n\n1. Select HEROIC before entering Auchindoun. Several original Draenor mechanic achievements do not credit on Mythic. Remove reactive damage and damaging pets when waiting for mechanics.\n\n2. Bring another player. At Azzakel, wait for Curtain of Flame before killing him; it is cast early in the fight. Move close to transfer the ticking debuff between the two players.\n\n3. Keep refreshing it by bouncing between players as you clear the platform route. Refresh immediately before using each teleporter and coordinate clicking together: the travel time and cinematic can consume its short duration.\n\n4. At Teron'gor, put the debuff on each participant needing credit, have them tag the boss and finish him before it expires. This personal achievement is NOT a required Glory of the Draenor Hero criterion.",
        stepCount = 4,
        waypoints = { { mapID = 535, x = 0.44799999999999995, y = 0.745, step = 1, label = "Auchindoun - entrance" } },
        sources = {
