    [9571] = {
        achievementId = 9571,
        name = "Broke Back Precipice",
        source = "Broke Back Precipice",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Two rare patrols and a separately summoned Pit Slayer.",
        acquisition = "Difficulty: Medium - Two rare patrols and a separately summoned Pit Slayer.\n\n1. Visit Broken Precipice in northern Draenor Nagrand. Take its assault or scouting missive so the Pit Slayer summoning object can be used when available.\n\n2. Find and defeat Bonebreaker and Durg Spinecrusher in the surrounding precipice. Patrol the area and revisit after respawns if either is missing.\n\n3. At the arena near 38.8,13.8, smash the head on the pike to summon Pit Slayer and defeat him. The head is not permanently available, so do not spend hours camping the pit without checking the assault and its object.",
        stepCount = 3,
        waypoints = { { mapID = 550, x = 0.38799999999999996, y = 0.138, step = 1, label = "Broke Back Precipice - activity area" } },
