    [9600] = {
        achievementId = 9600,
        name = "Monster Mash",
        source = "Monster Mash",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Consume the correct corpses with an attached parasite to make two transformations.",
        acquisition = "Difficulty: Medium - Consume the correct corpses with an attached parasite to make two transformations.\n\n1. Accept the Lost Veil Anzu assault/missive. Enter its southern boundary at 73.4,48.3 until the parasite attaches: look for its whisper/emote and Parasitic Growth effect. If no parasite responds, leave and re-enter before killing more enemies.\n\n2. Kill and loot goblins, then interact with their corpses while the parasite is attached. Consume five to transform into a Shadow Hulk. Ordinary kills without consuming corpses do not advance the transformation.\n\n3. Let the form expire or leave and return to reset. Repeat with five ogre corpses to become a Gluttonous Giant. Keep your assault incomplete while doing the interactions and use a fresh missive if it finishes too soon.",
        stepCount = 3,
        waypoints = { { mapID = 542, x = 0.7340000000000001, y = 0.483, step = 1, label = "Monster Mash - activity area" } },
        sources = {
            "https://www.wowhead.com/achievement=9600",
            "https://www.wowhead.com/achievement=9601#comments:id=3143286",
            "https://www.wowhead.com/achievement=9600#comments:id=5878864",
            "https://www.wowhead.com/achievement=9600#comments:id=6062448",
        },
        sourceURL = "https://www.wowhead.com/achievement=9600#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=9600",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [9601] = {
        achievementId = 9601,
        name = "King of the Monsters",
        source = "King of the Monsters",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Each of five rares must die while your short monster transformation is active.",
        acquisition = "Difficulty: Hard - Each of five rares must die while your short monster transformation is active.\n\n1. Accept the Lost Veil Anzu assault/missive, obtain its parasite at the southern entrance and use the Shadow Hulk transformation described in Monster Mash. Prefer steady flight: current comments report Skyriding removing the parasite/form.\n\n2. Find the required rare BEFORE consuming the fifth corpse. Prepare four consumed goblins, locate a live rare, then consume the fifth nearby to start your three-minute Shadow Hulk window. Kill that rare while transformed.\n\n3. Repeat for Morphed Sentient, Giga Sentinel, Gluttonous Giant, Mecha Plunderer and the RARE Shadow Hulk deep inside the marked cave. The ordinary Shadow Hulk version does not count. Only one rare may be available at a time; clear unwanted rares and revisit missing ones without assuming an exact spawn timer.\n\n4. Keep assault progress below 100%: completion can remove the form. Buy another missive for further attempts if necessary. Modern comments report unreliable Gluttonous Giant-form credit, which is why this route uses Shadow Hulk for the kills.",
        stepCount = 4,
        waypoints = {
