    [9602] = {
        achievementId = 9602,
        name = "Shoot For the Moon",
        source = "Shoot For the Moon",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Finish the zone's one-time bonus objectives and respect its outpost choices.",
        acquisition = "Difficulty: Medium - Finish the zone's one-time bonus objectives and respect its outpost choices.\n\n1. Establish this character's zone outpost where applicable and enable trivial-quest tracking. These are the original zone BONUS OBJECTIVES, not the Garrison Apexis assault dailies. Later Retail comments confirm the old level-50 disappearance bug was fixed; do not follow outdated instructions to freeze XP or require a Remix character.\n\n2. Enter each named bonus-objective area and complete the actual kill/interaction requirements shown in the objective tracker. Enter the cave for underground objectives. Leave only after the completion banner; ordinary kills outside the objective boundary do not count.\n\n3. Check the achievement's missing named criteria after each completion and visit only those still absent. If a bonus objective is missing, finish the local story handoff and enter its actual area rather than relying solely on a world-map icon.",
        stepCount = 3,
        waypoints = {
            { mapID = 539, x = 0.23, y = 0.32799999999999996, step = 2, label = "Bloodthorn Cave - enter cave" },
