    [9634] = {
        achievementId = 9634,
        name = "Charged Up",
        source = "Charged Up",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Kill thirty enemies inside an intact Arkonite Crystal's radius.",
        acquisition = "Difficulty: Easy - Kill thirty enemies inside an intact Arkonite Crystal's radius.\n\n1. Find a Tainted Arkonite Crystal in Shattrath Harbor. Check the felhound pit at 37.8,19 and the other mapped crystal areas if it is absent.\n\n2. Stand beside the crystal to receive Arkonite Empowerment. DO NOT CLICK OR DESTROY THE CRYSTAL. Pull Shadow Council enemies into its radius so both you and the targets are affected.\n\n3. Kill thirty affected enemies, waiting for respawns or bringing more nearby targets. Running away with the brief player buff and killing enemies outside the radius can miss credit. The intact crystal provides the effect, not a collectible carried item.",
        stepCount = 3,
