    [9639] = {
        achievementId = 9639,
        name = "Fight, Kill, Salute!",
        source = "Fight, Kill, Salute!",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Requires a level 3 Sanctum and an organized Highmaul Coliseum queue.",
        acquisition = "Difficulty: Hard - Requires a level 3 Sanctum and an organized Highmaul Coliseum queue.\n\n1. Earn The Bone Collector, upgrade your own Garrison and Gladiator's Sanctum to level 3, then walk outside the Garrison front gate for Gharg's Call of the Gladiator. Take the Sigil of Highmaul to Kharg outside Highmaul in Nagrand and accept Fight, Kill, Salute! (37083). If previously abandoned, check Kharg at Highmaul directly.\n\n2. Arrange fifteen eligible same-faction participants and queue through the Coliseum NPC. If a premade will not queue together, later comments describe one participant queueing first and inviting the others afterward. Confirm the live NPC's level and Broken Bone entry rules; current 2025 reports include level-70 entry, so the original fixed level-100 limit is obsolete.\n\n3. With Fight, Kill, Salute! in your quest log, earn its hundred qualifying Coliseum kills and turn it in, OR win the event for documented immediate quest completion. Tag opponents and stay alive long enough for credited deaths; outdoor Ashran kills do not fill the Coliseum objective.\n\n4. Stay through the concluding NPC scene and loot the appropriate winner's chest/reward if eligible. A winner can be locked out of requeueing for the week, so organize repeat participants/alts before starting. Very long queues reflect low participation; this remains obtainable with an organized group.",
        stepCount = 4,
        waypoints = { { mapID = 550, x = 0.33, y = 0.38, step = 1, label = "Kharg - Highmaul Coliseum quest / queue" } },
        sources = {
            "https://www.wowhead.com/achievement=9639",
            "https://www.wowhead.com/achievement=9639#comments:id=2086861",
            "https://www.wowhead.com/achievement=9639#comments:id=2856877",
            "https://www.wowhead.com/achievement=9725#comments:id=2045015",
            "https://www.wowhead.com/achievement=9725#comments:id=6078394",
        },
        sourceURL = "https://www.wowhead.com/achievement=9639#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=9639",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [9654] = {
        achievementId = 9654,
        name = "Mean and Green",
        source = "Mean and Green",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Collect ten stacking mutagen pools before the effect expires.",
        acquisition = "Difficulty: Easy - Collect ten stacking mutagen pools before the effect expires.\n\n1. Visit the Everbloom Wilds outdoor area east of the dungeon. Kill Twisted Guardians and Enthralled Mutants, then immediately walk through their short-lived green death pools.\n\n2. Each pool adds a Mutagen stack and extends its short duration. Chain nearby kills and collect ten stacks without letting the effect expire or leaving the area. The assault is not required for these death pools according to later Retail comments.",
        stepCount = 2,
        waypoints = { { mapID = 543, x = 0.7390000000000001, y = 0.3945, step = 1, label = "Mean and Green - activity area" } },
