    [9667] = {
        achievementId = 9667,
        name = "Burn it to the Ground",
        source = "Burn it to the Ground",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Burn one hundred distinct trees using looted flamethrowers.",
        acquisition = "Difficulty: Medium - Burn one hundred distinct trees using looted flamethrowers.\n\n1. Accept Assault on the Everbloom Wilds or its missive and find Iron Pyrotechs around 58,38. Kill one and click its dropped flamethrower to gain the extra-action weapon.\n\n2. Aim its cone through several unburned trees/stumps per charge. The weapon has limited energy, so line up clusters before firing and collect replacement flamethrowers as needed. Already burned trees do not give new credit.\n\n3. Burn one hundred trees across as many visits/missives as needed. Stop ordinary killing once you have a weapon: assault progress also comes from burning, and reaching 100% can disable further pickups. Start another missive if necessary.",
        stepCount = 3,
        waypoints = { { mapID = 543, x = 0.58, y = 0.38, step = 1, label = "Burn it to the Ground - activity area" } },
        sources = { "https://www.wowhead.com/achievement=9667", "https://www.wowhead.com/achievement=9667#comments:id=6034828" },
