    [9724] = {
        achievementId = 9724,
        name = "Taming Draenor",
        source = "Taming Draenor",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Defeat six distinct tamers with suitable family counters.",
        acquisition = "Difficulty: Medium - Defeat six distinct tamers with suitable family counters.\n\n1. Prepare a rare-quality level-25 roster and heal between tamers. You need one full victory over each listed tamer; a carried low-level pet is optional.\n\n2. Defeat Ashlei at Shadowmoon 50,31.2 with Dragonkin damage for her Magic pets and Mechanical damage for the Beast. Defeat Gargra at Frostfire 68.6,64.6 using Mechanical damage against her three Beasts.\n\n3. Defeat Cymre at Gorgrond 51,70.6 with Critter/Dragonkin/Elemental coverage for her mixed team. Do not kill the first enemy while its Dark Rebirth effect would revive it; stall or defend until that effect expires, then finish it.\n\n4. Defeat Taralune at Talador 49,80.4 with strong Magic attacks for Flying pets. Defeat Vesharr at Spires 46.2,45.4 using Magic damage on the flyers and Elemental damage on the Mechanical opponent.\n\n5. Defeat Tarr the Terrible near Nagrand 56.2,9.8 using Undead damage against his Humanoids. Check all six criteria. Complete daily quests separately when offered if you also want their rewards; the achievement is the six victories.",
        stepCount = 5,
        waypoints = {
            { mapID = 539, x = 0.5, y = 0.312, step = 2, label = "Ashlei" },
            { mapID = 525, x = 0.6859999999999999, y = 0.6459999999999999, step = 2, label = "Gargra" },
            { mapID = 543, x = 0.51, y = 0.706, step = 3, label = "Cymre Brightblade" },
            { mapID = 535, x = 0.49, y = 0.804, step = 4, label = "Taralune" },
