    [9725] = {
        achievementId = 9725,
        name = "The Last of Us",
        source = "The Last of Us",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Requires a level 3 Sanctum and an organized Highmaul Coliseum queue.",
        acquisition = "Difficulty: Hard - Requires a level 3 Sanctum and an organized Highmaul Coliseum queue.\n\n1. Earn The Bone Collector, upgrade your own Garrison and Gladiator's Sanctum to level 3, then walk outside the Garrison front gate for Gharg's Call of the Gladiator. Take the Sigil of Highmaul to Kharg outside Highmaul in Nagrand and accept Fight, Kill, Salute! (37083). If previously abandoned, check Kharg at Highmaul directly.\n\n2. Arrange fifteen eligible same-faction participants and queue through the Coliseum NPC. If a premade will not queue together, later comments describe one participant queueing first and inviting the others afterward. Confirm the live NPC's level and Broken Bone entry rules; current 2025 reports include level-70 entry, so the original fixed level-100 limit is obsolete.\n\n3. Win the free-for-all: tag opponents to gain the stacking buff when they die, preserve defensives and healing for the final survivors, then eliminate the last opponent. Do not leave after merely finishing the associated 100-kill quest; this feat specifically requires winning.\n\n4. Stay through the concluding NPC scene and loot the appropriate winner's chest/reward if eligible. A winner can be locked out of requeueing for the week, so organize repeat participants/alts before starting. Very long queues reflect low participation; this remains obtainable with an organized group.",
        stepCount = 4,
        waypoints = { { mapID = 550, x = 0.33, y = 0.38, step = 1, label = "Kharg - Highmaul Coliseum quest / queue" } },
        sources = {
            "https://www.wowhead.com/achievement=9725",
            "https://www.wowhead.com/achievement=9639#comments:id=2086861",
            "https://www.wowhead.com/achievement=9639#comments:id=2856877",
            "https://www.wowhead.com/achievement=9725#comments:id=2045015",
            "https://www.wowhead.com/achievement=9725#comments:id=6078394",
        },
        sourceURL = "https://www.wowhead.com/achievement=9725#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=9725",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [9728] = {
        achievementId = 9728,
        name = "Grand Treasure Hunter",
        source = "Grand Treasure Hunter",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Open 200 qualifying original Draenor treasures across six zones.",
        acquisition = "Difficulty: Medium - Open 200 qualifying original Draenor treasures across six zones.\n\n1. Finish a zone's main story achievement, then buy its treasure map from Grakis in Stormshield (48.3,33.2) or Srikka in Warspear (74.6,31.8). Learn the map to reveal treasure icons. Alternatively use already available treasure tracking; the map purchase is assistance, not an additional achievement requirement.\n\n2. Start with dense treasures around Shadowmoon Valley's Anguish Fortress or Gorgrond, then clear Spires, Talador, Frostfire and Nagrand as needed. Fly to high ledges and search caves rather than following old claims that Engineering or jumping toys are mandatory.\n\n3. Loot 200 different qualifying treasures and check the counter after each small circuit. Original-zone treasures count; Tanaan treasures and decorative Garrison pickups do not automatically advance this older total. Rare kills are not treasure discoveries.\n\n4. If short near the end, establish Gorgrond's outpost and use its Lumber Yard shredder or Arena boulder ability to open the corresponding extra treasure objects. Later replies document this resolving a 198/200 shortage. Nagrand is another reported source when some Frostfire/Shadowmoon pickups do not count.\n\n5. Complete the displayed total. Only the 100-treasure Master achievement is needed for Draenor Pathfinder; Grand's 200 is a separate goal. Useful original descriptions and source locations remain available alongside these guide choices.",
        stepCount = 5,
        waypoints = {
            { mapID = 622, x = 0.483, y = 0.332, step = 1, label = "Grakis - Alliance treasure maps" },
            { mapID = 624, x = 0.746, y = 0.318, step = 1, label = "Srikka - Horde treasure maps" },
            {
                mapID = 539,
                x = 0.38799999999999996,
                y = 0.42700000000000005,
                step = 2,
                label = "Anguish Fortress - dense treasure area",
            },
            { mapID = 543, x = 0.523, y = 0.597, step = 4, label = "Highpass outpost - extra treasure abilities" },
            { mapID = 543, x = 0.462, y = 0.696, step = 4, label = "Beastwatch outpost - extra treasure abilities" },
        },
        areaMaps = { 525, 539, 543, 535, 542, 550 },
        sources = {
            "https://www.wowhead.com/achievement=9728",
            "https://www.wowhead.com/achievement=9728#comments:id=5367856",
            "https://www.wowhead.com/achievement=9728#comments:id=6173100",
            "https://www.wowhead.com/achievement=10348#comments:id=6184170",
        },
        sourceURL = "https://www.wowhead.com/achievement=9728#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=9728",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
