    [34398]={questID=34398,name="Warlords of Draenor: The Dark Portal",instructions="Go to Archmage Khadgar at the foot of the Dark Portal in the present-day Blasted Lands and accept or hand in The Dark Portal. Complete his dialogue to enter the Tanaan introduction; an old pre-invasion Zidormi phase hides the correct NPC.",pickup={mapID=17,x=0.549,y=0.503},turnIn={mapID=17,x=0.549,y=0.503},pickupReference=true,sourceURL="https://www.wowhead.com/quest=34398",turnInReference=true},
