    [34392]={questID=34392,name="Onslaught's End",instructions="Disable the two fel spires of the Dark Portal. Start with Archmage Khadgar. Hand in to Archmage Khadgar.",pickup={mapID=577,x=0.548,y=0.482},turnIn={mapID=577,x=0.548,y=0.482},pickupReference=false,sourceURL="https://www.wowhead.com/quest=34392"},
