--[====[
Preserved inactive research: Data/Expansions/WarlordsOfDraenor/AchievementQuestRoutes.lua
This material is retained for reference and does not register character quest routes.

local _,TDP=...
local guides=TDP.CollectionWalkthroughs.achievements
local routes=TDP.CollectionQuestRoutes
local function copy(value)
    if type(value)~="table" then return value end
    local result={};for k,v in pairs(value) do result[k]=copy(v) end;return result
end
local function attach(ids,route)
    routes[route.key]=route
    for _,id in ipairs(ids) do
        local g=guides[id]
        if g then
            g.questRoutes=g.questRoutes or {}
            g.questRoutes[#g.questRoutes+1]=route
            g.keepReferencePins,g.separateQuestMap=true,true
        end
    end
end
local function fromExisting(ids,key,options)
    local original=routes[key]
    if not original then return end
    local route=copy(original)
    route.key="wod-achievement-"..key
    for k,v in pairs(options or {}) do route[k]=v end
    attach(ids,route)
end
for _,chapter in ipairs(TDP.WarlordsAchievementChapters) do
    local route=copy(chapter.route)
    for index,row in ipairs(route.quests) do
        local q=copy(TDP.WarlordsAchievementQuests[row.questID])
        if q then
            for k,v in pairs(row) do q[k]=v end
            route.quests[index]=q
        end
    end
    local ids={chapter.achievementID}
    if chapter.zone~="Introduction" and chapter.zone~="TanaanJungle" and chapter.zone~="GarrisonCampaign" and chapter.zone~="ShadowTrail" then
        ids[#ids+1]=route.faction=="Alliance" and 9833 or 9923
        ids[#ids+1]=10018
    end
    if chapter.zone=="SpiresOfArak" then
        if chapter.chapter=="Chain.PinchwhistleGearworks" then ids[#ids+1]=9468 end
        if chapter.chapter:find("ShadowsGather") or chapter.chapter:find("VeilZekk") or chapter.chapter=="Chain.SecretsOfTheTalonpriests" or chapter.chapter=="Chain.TheGodsOfArak" or chapter.chapter=="Chain.LegacyOfTheApexis" or chapter.chapter=="Chain.TerokksLegend" then ids[#ids+1]=9072 end
        ids[#ids+1]=9499
    end
    if chapter.zone=="Gorgrond" then
        if chapter.chapter:find("SparringArena") or chapter.chapter=="Chain.WeNeedAnOutpost" or chapter.chapter=="Chain.YourBaseYourChoice" then ids[#ids+1]=9402 end
        if chapter.chapter:find("LumberYard") or chapter.chapter=="Chain.WeNeedAnOutpost" or chapter.chapter=="Chain.YourBaseYourChoice" then ids[#ids+1]=9401 end
    end
    if chapter.zone=="TanaanJungle" then
        ids[#ids+1]=route.faction=="Alliance" and 10072 or 10265
        -- The Invasion chapter completes at the Assault Base. Optional later
        -- fleet upgrades do not become campaign prerequisites.
        if chapter.chapter:find("TheInvasionOfTanaan") then
            local last=route.faction=="Alliance" and 38445 or 37935
            local qs={};for _,q in ipairs(route.quests) do qs[#qs+1]=q;if q.questID==last then break end end
            route.quests,route.endQuestID=qs,last
        end
    end
    attach(ids,route)
end
for _,side in ipairs({"Alliance","Horde"}) do
    local a=side=="Alliance"
    local key=side:lower()
    for _,mount in ipairs(TDP.WarlordsStableMounts) do
        local original=routes["wod-stables-"..mount[1].."-"..key]
        if original then
            fromExisting({9526,9540,9706},original.key)
            local capture=copy(original)
            capture.key="wod-achievement-capture-"..mount[1].."-"..key
            capture.name=mount[5].." - capture"
            capture.quests={copy(original.quests[1])}
            capture.endQuestID=capture.quests[1].questID
            attach({9538,9539,9705},capture)
        end
    end
    local naval={10017,10036,10156,10154,10161,10155,10159,10160,10162,10163,10170,10172,10255,10173,10275,10174,10276,10164,10165,10166,10167,10307,10256,10258,10177,10169,10168}
    fromExisting(naval,"wod-tanaan-access-"..key)
    fromExisting(naval,"wod-shipyard-"..key)
    local level3=a and 39068 or 39246
    attach({10168,10165},{key="wod-achievement-shipyard-level3-"..key,name="Naval Domination - "..side,faction=side,version=1,reviewedAt="2026-11-15",quests={{questID=level3,name="Naval Domination",requires={a and 39067 or 39245},pickup={mapID=a and 539 or 525,x=a and .275 or .42,y=a and .113 or .71},pickupReference=true,turnInReference=true,
        instructions="Accept Naval Domination after the level 2 Shipyard upgrade. Complete its twenty-five naval treasure missions, save 2,500 Garrison Resources and 2,500 gold, then turn in at the Shipyard. Learn the level 3 blueprint, pay for construction and finalize the completed upgrade.",sourceURL="https://www.wowhead.com/quest="..level3}},endQuestID=level3})
    fromExisting(a and {9828,9912,10015} or {9897,9914,10016},"wod-toy-audiophone-"..key)
    fromExisting({9924},"wod-toy-camera-"..key)
    fromExisting({9639,9725,9508,9738},"wod-toy-coliseum-"..key)
    fromExisting({9429},"wod-toy-treessassin-"..key)
    for _,suffix in ipairs({"saberstalkers","awakened","ensemble"}) do
        local route=routes["wod-cosmetic-"..suffix.."-"..key]
        if route then
            local r=copy(route)
            r.key="wod-achievement-diplomat-"..suffix.."-"..key
            r.standing=7
            r.rankReputationTarget,r.rankReputationLabel=21000,"Revered"
            r.satisfiedText="Revered - this Tanaan Diplomat faction is ready"
            r.satisfiedPin=nil
            r.after="Revered satisfies this achievement's faction criterion. Exalted tabard purchases are separate. Repeat the available reputation method or use eligible tokens until Revered."
            for _,q in ipairs(r.repeatableQuests or {}) do q.instructions=q.instructions:gsub("until Exalted","until Revered"):gsub("for this tabard is Exalted, not Revered","for this achievement is Revered") end
            attach(a and {10350,10018} or {10349,10018},r)
        end
    end
end
