            local id=index==#c[4] and (a and c[2] or c[3]) or row[1]
            q[#q+1]={questID=id,name=row[2],instructions=row[6],sourceURL="https://www.wowhead.com/quest="..id,
                pickup=index==1 and {mapID=side[2],x=side[3]/100,y=side[4]/100} or {mapID=c[4][index-1][3],x=c[4][index-1][4]/100,y=c[4][index-1][5]/100},
                pickupReference=true,mobilePickup=index>1,pickupLabel=index>1 and "Complete the previous stage's quest popup / check Treasure Contracts" or nil,
                requires=index==1 and {} or {q[#q].questID},
                objective={mapID=row[3],x=row[4]/100,y=row[5]/100},objectiveReference=true,
                turnIn=index==#c[4] and {mapID=side[2],x=side[3]/100,y=side[4]/100} or nil,turnInReference=index==#c[4]}
        end
        local route={key="wod-relic-"..c[7].."-"..side[1]:lower(),name=c[1],faction=side[1],version=1,reviewedAt="2026-11-15",quests=q,endQuestID=q[#q].questID,
            after="If a later stage was abandoned, check the book of Treasure Contracts beside Harrison / Daltry. Finish the final Garrison hand-in for chapter credit; the mid-chain popups do not finish the whole contract."}
        TDP.CollectionQuestRoutes[route.key]=route;ownRoutes[#ownRoutes+1]=route
        local offset=#steps
        for _,row in ipairs(c[4]) do steps[#steps+1]=c[1].." - "..row[2]..": "..row[6];points[#points+1]=pin(row[3],row[4],row[5],#steps,row[2]) end
        for _,point in ipairs(c[5]) do
            local extra={};for k,v in pairs(point) do extra[k]=v end
            extra.step=offset+point.step-1
            points[#points+1]=extra
        end
    end
    steps[#steps+1]="Complete all six final hand-ins for Master Relic Hunter. For Don't Call Me Junior, the current criterion is Master Relic Hunter; the original Garrison Campaign and Exploration Mission Master are not additional requirements. Ask Harrison to join as a follower after the six contracts; having another character's account achievement does not complete these local quests."
    for _,id in ipairs(a and {9825,9928} or {9836,9901}) do
        add(id,(id==9825 or id==9836) and "Master Relic Hunter" or "Don't Call Me Junior","hard","Six rotating relic contracts with several puzzles and faction-specific final hand-ins.",steps,points,{"https://www.wowhead.com/quest=37914#comments:id=2125357","https://www.wowhead.com/quest=37881#comments:id=2124132","https://www.wowhead.com/quest=37848#comments:id=2126782","https://www.wowhead.com/quest=37788#comments:id=2130765","https://www.wowhead.com/quest=37941#comments:id=2131805","https://www.wowhead.com/quest=37973#comments:id=2128892"})
        guides[id].questRoutes=ownRoutes
    end
end

