local function q(id,name,text,point,requires,options)
    local quest={questID=id,name=name,instructions=text,pickup=point,turnIn=point,requires=requires or {},sourceURL="https://www.wowhead.com/quest="..id}
    for k,v in pairs(options or {}) do quest[k]=v end
    return quest
end
