    route({9499},"bodyguard-ashran","Recruit "..(a and "Delvar Ironfist" or "Vivianne"),{
        q(ash[1],"Ashran Appearance","After unlocking your Garrison follower mission table, take Ashran Appearance in the Town Hall. Speak to your Garrison flight master and choose the special Stormshield / Warspear flight. A capital teleport does not credit the required flight. Report to Private Tristan / Stomphoof after landing.",home,{}, {pickupReference=true,turnIn=town,objective=town,objectiveReference=true}),
        q(ash[2],a and "Host Howell" or "Warspear Welcome","Report to "..(a and "Lieutenant Howell inside Hero's Rest Inn" or "Lieutenant Kragil inside Brokenspear Tavern").." and take Inspiring Ashran.",town,{ash[1]}),
