    for index,row in ipairs(TDP.WarlordsAchievementAssaults) do
        local id=assaultDailyIDs[index][a and 1 or 2]
        local flag=row[a and 6 or 7]
        attach(a and {9564,10018} or {9562,10018},{key="wod-achievement-assault-"..id,name="Assault on "..row[1],faction=side,version=1,reviewedAt="2026-11-15",quests={
            q(id,"Assault on "..row[1],"Take this Garrison table daily or ACCEPT its Scouting Missive alternative before farming. "..row[5].." Fill the accepted objective bar and return the quest. The route recognizes this character's completed assault criterion; an unrelated campaign bonus objective is not the same checklist.",home,{}, {pickupReference=true,turnInReference=true,objective=p(row[2],row[3],row[4]),objectiveReference=true,altQuests={flag}}),
        },endQuestID=flag,after="The missive is an alternative starter for the same assault. Use the guide's static assault-area map alongside the accepted quest's live objective."})
    end
    local original=TDP.CollectionQuestRoutes["wod-cosmetic-ensemble-"..side:lower()]
    if original then
        local route=copy(original)
        route.key="wod-achievement-tanaan-daily-access-"..side:lower()
        route.name="Tanaan daily assault access - "..side
        route.factionID,route.rankFactionID,route.standing=nil,nil,nil
        route.satisfiedPin,route.satisfiedText=nil,nil
        for _,quest in ipairs(route.repeatableQuests or {}) do quest.activeOnly=true end
        route.after="After Commander in the Field, choose an offered assault at the Tanaan command table. Only accepted daily quests are shown as active destinations; the addon does not guess today's rotating offer. Complete each of the seven distinct areas for Draenor's Last Stand."
        attach(a and {10068,10072} or {10075,10265},route)
    end
end
